/* ÇEVİRİ jv · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("jv","olay",{
"OLAYLAR:1299-01:0":{"b": ["Adege Kadipaten Utsmaniyah", "9f0b7c0a"], "d": ["Wiwite Osman Ghazi saka suku Kayi tumindak mardika ing sakiwa-tengene Söğüt-Domaniç ditampa minangka wiwitan sing wis dadi tradhisi kanggo adege Nagara Utsmaniyah; sawetara sejarawan nganggep kamenangan Bapheus ing taun 1302 minangka titik owah-owahan sing sejatine. Amarga panggonane ing tlatah tapel wates Bizantium, kadipaten iku kanthi cepet nglumpukake kakuwatan liwat serangan ghaza. Ing kahanan nalika warisan Seljuk lagi ajur, Osman Ghazi nglumpukake para ahi, para ghazi lan wong Turkmen sing urip ngumbara ing sakiwa-tengene; sesambungan sing diadegake karo Syekh Edebali dianggep minangka dhasar legitimasi rohani kadipaten. Panggonan liya sing digabungake ing tanggal sing padha: İnegöl, Yarhisar.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Penaklukan Bursa", "98c727fa"], "d": ["Bursa, sing wis pirang-pirang taun dikepung, nyerah marang Orhan Ghazi sing mimpin tahap pungkasan pengepungan; kutha iku didadèkaké ibu kutha gedhé kapisan kadipaten. Dicritakake yen kabar penaklukan iku diaturake marang Osman Ghazi sing lagi sekarat; miturut wasiyate, Osman Ghazi disarèkaké ing Bursa. Ora suwe kutha iku dilengkapi mesjid, dapur umum (imaret) lan madrasah, banjur dadi conto tata kutha Utsmaniyah ing mangsa wiwitan.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Penaklukan Iznik", "a846a811"], "d": ["Iznik (Nikaia), salah siji pusat Bizantium sing paling wigati ing Anatolia, kelangan pangarep-arep kanggo bertahan sawise kamenangan Pelekanon ing taun 1329, banjur nyerah marang Orhan Ghazi. Madrasah Utsmaniyah kapisan diadegake ing kene, lan ulama kaya Dâvûd-i Kayserî wiwit mulang; kutha iku dadi pusat ilmu ing mangsa wiwitan. Greja Hagia Sophia diowahi dadi mesjid, nuduhake conto wiwitan saka tradhisi penaklukan.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Penaklukan Izmit", "06a35035"], "d": ["Kanthi tibane Izmit (Nikomedia), bèntèng wigati pungkasan Bizantium ing sisih Anatolia uga mlebu ing pamaréntahan Utsmaniyah; kabeh semenanjung Kocaeli nganti tekan pesisir ing sabrangé Istanbul dadi wilayah Utsmaniyah. Kanthi mangkono kadipaten nguwasani kabeh pesisir kidul lan wétan Segara Marmara lan nyiapake dhasar kanggo nyabrang menyang Rumelia.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Bèntèng Cimpe — nyabrang menyang Rumelia", "c2f0a07d"], "d": ["Suleyman Pasya, putrané Orhan Ghazi, ing taun 1352 wis ndadèkaké Bèntèng Cimpe, sing diwènèhaké nalika perang sedulur Bizantium, minangka pangkalan; sawisé lindhu gedhé sing ngrusak Gallipoli ing Maret 1354, bèntèng-bèntèng sing ditinggal kosong kanthi cepet dikuwataké lan semenanjung iku diowahi dadi pancadan Utsmaniyah sing tetep. Tumindak iki, sing didhukung kanthi manggonaké pendhudhuk Turkmen sing digawa saka Anatolia, minangka wiwitan anané Utsmaniyah ing bawana Éropah sing bakal lumaku luwih saka 550 taun.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Penaklukan Edirne", "2f54ebb0"], "d": ["Direbuté Edirne (Adrianopolis), kutha kunci ing Trakia, nemtokaké pangkalan utama lan arah penaklukan Balkan; tanggal penaklukané isih dadi pasulayan ing sumber-sumber, antarané 1361 lan 1369. Ora suwe kutha iku didadèkaké ibu kutha, sing ngumumaké yen pusat bobot nagara wis pindhah menyang Rumelia; kutha iku tetep dadi kutha tahta (payitaht) suwéné kira-kira 90 taun nganti penaklukan Istanbul.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Murad I munggah tahta", "f8d48a26"], "d": ["Murad I (Hudavendigar), sing munggah tahta sawise sédané Orhan Ghazi, sajrone 27 taun mréntah nggawa nagara saka kadipaten tapel wates dadi rerangkèn kekaisaran. Liwat sistem pencik dipasang dhasar Korps Yenisari, tatanan timar disebarluaskan, Beylerbeylik Rumelia diadegake lan lembaga wazir dikuwataké. Penaklukan Balkan dadi kawicaksanan nagara sing tumata ing mangsa pamaréntahané.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Perang Kosovo I — Murad I gugur syahid", "10b8ddc9"], "d": ["Persekutuan Balkan sing dipimpin Pangeran Lazar dikalahaké kanthi mesthi ing Dhataran Kosovo; Serbia mlebu ing sangisoré kakuwasaan dhuwur Utsmaniyah. Murad I, sing lagi ngubengi papan perang, disuduk nganggo keris cilik déning bangsawan Serbia Miloš Obilić nganti gugur syahid — panjenengané iku siji-sijiné sultan Utsmaniyah sing séda ing papan perang. Minangka gantiné, Bayezid Yildirim diunggahaké tahta ing pakemahan; sedulure, Yakub Celebi, dijiret nganti mati, lan iki dadi salah siji conto wiwitan sing dimangertèni saka praktik matèni sedulur.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Kamenangan Nikopolis", "75716e96"], "d": ["Wadyabala Salib gedhé sing diklumpukaké amarga pangundangé raja Hongaria Sigismund, sing uga dimèlu para ksatria Prancis lan Burgundia, dikalahaké kanthi abot déning Bayezid Yildirim ing ngarep Nikopolis ing pinggir Kali Donau. Kamenangan iku nemtokaké kakuwasaan Utsmaniyah ing Bulgaria; sajrone sak generasi ora bisa dianakaké ekspedisi Salib gedhé ing Éropah.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Perang Ankara — Mangsa Interregnum (Fetret) diwiwiti", "b4a99d96"], "d": ["Ing kekalahan abot nglawan wadyabala Timur ing Dhataran Cubuk, Bayezid Yildirim ditawan lan sawetara sasi sawisé séda ing tawanan. Timur nguripaké manèh kadipaten-kadipaten Anatolia; wilayah Utsmaniyah dipérang ing antarané para putrané Bayezid lan diwiwiti rebutan tahta sing lumaku 11 taun (Mangsa Interregnum). Mangsa iki, krisis paling abot sing dialami nagara wiwit ngadegé, ngukir wigatiné tatanan sing kapusat ing éling-élingané bangsa Utsmaniyah. Pamukiman liya sing ucul ing tanggal sing padha: Datça, Marmaris, Fethiye (Makri), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Bursa), İnegöl, Bèntèng Aydos, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, Pulo İmralı, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Kios), Söğüt, Bilecik, Eskişehir, Bursa, Iznik, Izmit, Balıkesir, Çanakkale, Bergama, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Stara Zagora (Eski Zağra), Tatarpazarcığı, İhtiman, Kyustendil, Petriç, Nevrokop (Gotse Delchev), Drama, Gallipoli, Cimpe, Edirne, Dimetoka, Kırklareli, Tekirdağ, Plovdiv, Sofia, Niš, Vidin, Tarnovo, Varna, Shumen, Silistra, Nikopolis, Ruse, Thessaloniki, Serres, Kavala, Skopje, Manastir, Ohrid, Yenişehir (Larissa), Tırhala, İzdin (Lamia), Pleven, Gümülcine, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M.Kemalpaşa), Mihaliç (Karacabey), Constanța, Gölyazı (Apollonia).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Mehmed Celebi mbangun manèh manunggalé nagara", "03413dfd"], "d": ["Mehmed I, sing ngalahaké Musa Celebi ing Çamurlu ing paprangan pungkasan antarané para sedulur, manunggalaké wilayah nagara ing sangisoré siji pamaréntahan; mula saka iku panjenengané dianggep 'pangadeg nagara sing kapindho'. Ing mangsa pamaréntahané, susunan nagara sing wis rusak didandani, sesambungan karo kadipaten-kadipaten Anatolia diimbangaké, lan ing Rumelia ditindakaké kawicaksanan tentrem sing ngati-ati. Pamukiman liya ing peta sing ing tanggal sing padha bali saka mangsa Interregnum menyang pamaréntahan Utsmaniyah: Absu (Hypsu), Adranos (Orhaneli), Akhisar (Pamukova).", "45315d2d"]},
"OLAYLAR:1416-05-01:0":{"b": ["Pambrontakan Syekh Bedreddin", "e0a072ca"], "d": ["Obahé agama lan masarakat sing tuwuh ing sakiwa-tengené Syekh Bedreddin, ahli fikih lan sufi gedhé sing naté dadi hakim militèr (kazasker) ing Mangsa Interregnum, mbledhos bebarengan karo pambrontakan Börklüce Mustafa ing Karaburun lan Torlak Kemal ing Manisa. Pambrontakan-pambrontakan iku dipadhemaké kanthi getih; Bedreddin dicekel ing Deliorman lan diukum pati ing Serres. Kedadéan iki ninggalaké tilas jero ing sastra lan panulisan sejarah minangka pambrontakan masarakat lan mahdiisme gedhé sing paling wiwitan ing sejarah Utsmaniyah.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Kamenangan Varna", "f739eedc"], "d": ["Wadyabala Salib Hongaria-Polandia, sing mudhun ngidul kanthi nyulayani prajanjèn Szeged, ditumpes ing Varna déning Murad II, sing bali mimpin wadyabala sawisé lèngsèr saka tahta; raja enom Ladislaus III séda ing papan perang. Kamenangan iku ngilangaké kalodhangan gedhé pungkasan kanggo campur tangan manca sing ditujokaké kanggo nyingkiraké anané Utsmaniyah ing Balkan, lan njamin dalan menyang penaklukan Istanbul.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Perang Kosovo II", "ebe0b662"], "d": ["Wadyabala John Hunyadi, sing péngin males kekalahan Varna, dikalahaké kanthi mesthi déning Murad II ing paprangan sengit sing lumaku telung dina. Iki perang gedhé pungkasan ing papan jembar sing ditindakaké para Salib nglawan Utsmaniyah ing Balkan; kanthi kamenangan iki, kakuwasaan Utsmaniyah ing kidul Kali Donau wis mapan lan ora bisa dibalèkaké manèh.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Penaklukan Istanbul", "583d5e3e"], "d": ["Sawisé pengepungan sing lumaku sèket papat dina (6 April–29 Mei 1453), ing ésuké tanggal 29 Mei wadyabala Utsmaniyah ngliwati témbok-témbok lan mlebu kutha; kaisar pungkasan, Konstantinus XI, tiwas ing peperangan, lan Kekaisaran Romawi Wétan sing umuré 1100 taun dadi sejarah. Sultan sing isih enom iku nampa gelar 'Al-Fatih' (Sang Penakluk), ndadèkaké kutha iku ibu kutha lan ngowahi Hagia Sophia dadi mesjid; ora suwe kutha iku diuripaké manèh liwat panggonan pendhudhuk lan pambangunan. Miturut TDV, Silivri lan Vize lagi ditaklukaké kanthi mesthi ing taun 1453; miturut artikel TDV bab Limnos, pulo iku mlebu pamaréntahan Utsmaniyah sanalika sawisé penaklukan lan dipasrahaké marang kulawarga Gattilusio kanthi syarat mbayar upeti. Ing atlas, Silivri, Vize lan Limnos kacathet pindhah saka Bizantium menyang Utsmaniyah wiwit dina iki (Limnos minangka tanah sing mbayar upeti). Pangecoran mriyem raseksa, kapal-kapal sing dilakokaké liwat dharatan, lan tatanan pengepungan ing ngarep témbok dianggep minangka pucuking teknik militèr ing jaman iku. Ing panulisan sejarah Éropah, penaklukan iki kaétung minangka salah siji tanggal lambang pungkasané Abad Pertengahan.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["Penaklukan Trebizond", "15f52403"], "d": ["Ing pungkasané ekspedisi Segara Ireng sing abot, sing ditindakaké Al-Fatih bebarengan nganggo wadyabala dharat lan armada, Kekaisaran Yunani Trebizond nyerah; kanthi disingkiraké sisa pungkasan donya Bizantium iki ing Anatolia, kabeh pesisir kidul Segara Ireng mlebu ing kakuwasaan Utsmaniyah. Dipungkasiné wangsa Komnenos nguwataké pengakuné Al-Fatih minangka 'panguwasa rong segara lan rong dharatan'. Panggonan liya sing digabungake ing tanggal sing padha: Giresun, Rize.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Penaklukan pungkasan Silifke — pecahé perlawanan pungkasan Karaman", "d988bee4"], "d": ["Bèntèng Silifke ing taun 1472 wis sapisan nyerah marang Gedik Ahmed Pasya, nanging ing taun sing padha Kasim Bey saka Karaman, kanthi pitulungan armada Salib ing Segara Tengah, ngrebut manèh bèntèng iku. Sawisé kamenangan Otlukbeli, Al-Fatih menehi tugas marang putrané lan Gedik Ahmed Pasya supaya nguwasani tlatah iku kanthi mesthi; kanthi pitulungané para tukang mriyem sing biyèn melu Utsmaniyah, gudhang mesiu diobong lan bèntèng iku cepet dirubuhaké. Kanthi mangkono perlawanan pungkasan wong Karaman ing pagunungan Taşeli-İçel dipecah; panyingkiran kadipaten iku bakal rampung ing taun 1474.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Perang Otlukbeli", "42c7194e"], "d": ["Panguwasa Aq Qoyunlu, Uzun Hasan, sing wis dadi kakuwatan gedhé ing Wétan lan sekutu karo Venesia, ngalami kekalahan abot ing Otlukbeli nglawan wadyabala Al-Fatih sing nganggo gegaman geni. Kamenangan iku nemtokaké unggulé Utsmaniyah ing Anatolia; uga dadi bukti wiwitan unggulé wadyabala pusat sing nganggo mriyem lan bedhil nglawan wadyabala klasik. Miturut artikel TDV bab Gümüşhane, kutha iku wiwit taun 1467 ana ing kakuwasaan Aq Qoyunlu; kakuwasaan iku rampung amarga kekalahan Otlukbeli lan Gümüşhane pindhah kanthi mesthi menyang kakuwasaan Utsmaniyah.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["Krimea mlebu ing pangayoman Utsmaniyah", "44e3f7c8"], "d": ["Armada sing dipimpin Gedik Ahmed Pasya naklukaké kutha-kutha pesisir kidul Krimea, kawitan Kaffa sing ana ing tangané wong Genoa; pesisir iku didadèkaké sanjak Utsmaniyah langsung. Déné Kasultanan (Khanat) Krimea ing sangisoré Mengli Giray dadi nagara bawahan sing oleh hak istiméwa lan ngakoni kakuwasaan dhuwur Utsmaniyah, banjur sajrone telung abad dadi watu dhasar politik ing sisih lor; Segara Ireng saiki sejatiné wis dadi segara jero Utsmaniyah. Panggonan liya sing digabungake ing tanggal sing padha: Bakhchysarai, Kerch, Azak.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Sédané Al-Fatih — prakara Sultan Cem", "190ecf01"], "d": ["Sawisé Al-Fatih séda dumadakan ing tengah dalan ekspedisi, Bayezid II munggah tahta; sedulure, Sultan Cem, sing ngaku duwé hak ing kasultanan, ndhawuhaké khutbah diwaca lan dhuwit dicithak nganggo jenengé ing Bursa. Sawisé kalah, panjenengané ngungsi dhisik menyang Mamluk, banjur menyang para ksatria Rodhos; Cem, sing ing tangané para ksatria lan kapausan dadi alat tawar-tinawar diplomasi Éropah, séda ing Napoli ing taun 1495. Prakara iki meksa politik njaba Utsmaniyah tumindak ngati-ati suwéné limalas taun.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Kamenangan Chaldiran", "fea64ebb"], "d": ["Yavuz Sultan Selim, sing péngin mbrastha nganti oyodé ancaman saka propaganda Safawiyah ing Anatolia, ngalahaké wadyabala Syah Ismail kanthi abot ing Dhataran Chaldiran amarga unggul ing mriyem lan bedhil. Tabriz dilebeti; Anatolia Wétan lan Kidul-Wétan sarta jalur Mosul-Diyarbakır digabungaké ing pamaréntahan Utsmaniyah. Kanthi usahané Idris Bitlisi, para bey Kurdi manut marang Utsmaniyah, sing mbentuk kerangka tapel wates wétan sing bakal lumaku pirang-pirang abad.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Kamenangan Marj Dabiq", "07d254d3"], "d": ["Wadyabala Mamluk dibubaraké sajrone sawetara jam ing Marj Dabiq ing sisih lor Aleppo; sultan sepuh Qansuh al-Ghawri séda nalika perang. Kanthi kamenangan sing mbukak amba-amba gapura Aleppo lan Damaskus, Suriah, Libanon lan Palestina pindhah menyang pamaréntahan Utsmaniyah; dalan kanggo ekspedisi Mesir sing bakal mungkasi Nagara Mamluk wis kabukak.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ridaniyah — penaklukan Mesir lan khilafah", "caf378d6"], "d": ["Wadyabala Utsmaniyah sing kanthi cepet nyabrang ara-ara samun Sinai njebol garis pertahanan Tumanbay ing Ridaniyah banjur mlebu Kairo; Tumanbay, sing isih nglawan, dicekel lan diukum pati, lan Nagara Mamluk dadi sejarah. Mesir, Hijaz lan kutha-kutha suci mlebu pamaréntahan Utsmaniyah; khalifah Abbasiyah lan barang-barang suci digawa menyang Istanbul. Kanthi pindhahé khilafah menyang wangsa Utsmaniyah, para sultan ngemban pengaku dadi pimpinan donya Islam; kontrol Dalan Rempah-rempah uga menehi kekaisaran bathi gedhé. Panggonan liya sing digabungake ing tanggal sing padha: Akko, Maan, Sidon, Kerak.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Sultan Sulaiman Kanuni munggah tahta", "f6512269"], "d": ["Pamaréntahan 46 taun Sulaiman I, sing munggah tahta minangka siji-sijiné putra lanang sawisé sédané Yavuz, dianggep minangka pucuk politik, militèr, kukum lan budaya kekaisaran. Kitab-kitab undhang-undhang (kanunname) sing nata kukum adat ndadèkaké panjenengané oleh gelar 'Kanuni' (Sang Panata Kukum); ing Kulon panjenengané disebut 'sing Agung' (Magnificent). Karya-karyané arsitèk Sinan, jaman emas sastra divan, lan unggulé armada ing Segara Tengah dadi lambang jaman iki.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Penaklukan Beograd", "59ef5cec"], "d": ["Beograd, sing ora bisa direbut Al-Fatih ing taun 1456 lan dianggep 'kunci Éropah Tengah', tiba ing ekspedisi kapisan Kanuni liwat pengepungan ing tempuran Kali Donau lan Sava. Garis pertahanan kidul Hongaria ambruk; penaklukan iki mbukak lawang kanggo gerakan ing Éropah Tengah sing tekan Mohács limang taun candhaké lan tekan panggabungan Buda rong puluh taun candhaké.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Penaklukan Rodhos", "807bbb1e"], "d": ["Rodhos, pangkalan para Ksatria Santo Yohanes sing ngancam dalan laut Segara Tengah Wétan lan dalan kaji, sawisé pengepungan getih sing lumaku pirang-pirang sasi nyerah kanthi prajanjèn penyerahan; para ksatria diidinaké ninggalaké pulo kanthi bébas (sabanjuré padha manggon ing Malta). Keamanan pesisir Anatolia kajamin lan jalur laut Istanbul-Mesir mlebu ing kontrol Utsmaniyah tanpa pedhot.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Perang Mohács", "f3418b0d"], "d": ["Wadyabala Hongaria dirusak ing Dhataran Mohács sajrone kira-kira rong jam amarga tembakan mriyem lan unggulé gerakan; Raja Louis II séda ing rawa nalika mlayu. Mohács, salah siji perang gedhé ing papan jembar sing paling cepet dimenangaké ing sejarah Utsmaniyah, sejatiné mungkasi krajan Hongaria sing mardika lan mbukak jaman persaingan Utsmaniyah-Habsburg ing Éropah Tengah.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["Pengepungan Wina I", "dc49ea4f"], "d": ["Ing ekspedisi sing dianakaké nglawan campur tangané wangsa Habsburg ing tahta Hongaria, wadyabala Utsmaniyah ngepung Wina; amarga mriyem abot ditinggal ing dalan, mangsa adhem teka luwih awal lan angelé pasokan, pengepungan dicabut sawisé telung minggu. Senajan kutha iku ora bisa direbut, pengaruh Utsmaniyah ing Hongaria tetep dijaga; ngarep Wina dadi tandha wates jangkauan logistik kekaisaran ing Éropah Tengah.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Penaklukan Baghdad — Ekspedisi Rong Irak", "897092c3"], "d": ["Ing ekspedisi marang 'Rong Irak' (Irak Arab lan Irak Persia), sing dilebeti dhisik Tabriz, banjur Baghdad tanpa perang; direbuté ibu kutha lawas Abbasiyah ndadèkaké panguwasa Utsmaniyah oleh kawibawan gedhé ing donya Islam. Makam Imam A'zham Abu Hanifah dipulihaké; kanthi digabungaké Baghdad lan Basra, wilayah Utsmaniyah tekan Teluk Persia. Panggonan liya sing digabungake ing tanggal sing padha: Kirkuk, Karbala.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Kamenangan Laut Preveza", "30dc0f97"], "d": ["Armada Salib sing dibentuk dipimpin Paus, senajan luwih akèh cacahé, dibubaraké ing lepas pesisir Preveza déning taktik Barbarossa sing pinter nggunakaké angin lan pesisir; Andrea Doria ninggalaké papan perang. Kamenangan iku ngadegaké unggulé laut Utsmaniyah ing Segara Tengah tanpa tandhingan sing bakal lumaku kira-kira 33 taun; ing tradhisi pelayaran Turki, iki tanggal lambang Dina Angkatan Laut. Panggonan liya sing digabungake ing tanggal sing padha: Aden, Bender.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Panggabungan Buda — Hongaria dadi provinsi Utsmaniyah", "db53b244"], "d": ["Kanuni, sing budhal ekspedisi amarga wangsa Habsburg ngepung Buda, sawisé nylametaké kutha iku njupuk Hongaria Tengah ing pamaréntahan Utsmaniyah langsung lan ngadegaké Beylerbeylik Buda; déné Transilvania didadèkaké kapangéranan otonom sing manut marang Utsmaniyah. Tatanan Hongaria sing dipérang telu iki lumaku kira-kira 150 taun lan mbentuk rerangkèn pamaréntahan Utsmaniyah sing tetep ing Éropah Tengah.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Prajanjèn Amasya", "a5afe0d1"], "d": ["Iki prajanjèn tentrem resmi kapisan sing mungkasi perang Utsmaniyah-Safawiyah sing wis lumaku pirang-pirang taun. Baghdad lan Irak tetep ing Utsmaniyah, tapel wates Anatolia Wétan diakoni bebarengan kanggo kaping pisan; Safawiyah saguh ngendheg propaganda Syiah ing wilayah Utsmaniyah, lan Utsmaniyah saguh njamin keamanan lelungané para kaji Iran. Prajanjèn iku dadi conto kapisan kerangka kukum sesambungan antarané rong nagara.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Szigetvár — sédané Kanuni", "e2917ed2"], "d": ["Kanuni, sing umuré 72 taun, séda ing kémahé sawetara jam sadurungé tibané Bèntèng Szigetvár, sing dikepung ing ekspedisiné kaping telulas; Sokollu Mehmed Pasya ndhelikaké sédané pirang-pirang minggu supaya wadyabala ora bubar. Bèntèng direbut, nanging nagara wis kelangan sultan sing paling suwé mréntah lan paling gemilang; putrané, Selim II, munggah tahta, lan bobot para wazir agung ing pamaréntahan nagara wiwit tambah.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Penaklukan Siprus", "e364a2b3"], "d": ["Ing taun 1570 wadyabala ndharat ing Siprus sing diprentah Venesia; Nikosia cepet tiba, déné Famagusta lagi nyerah sawisé pengepungan sewelas sasi ing Agustus 1571. Pulo iku, sing wigati banget kanggo keamanan dalan dagang lan kaji ing Segara Tengah Wétan, ditata dadi beylerbeylik lan pendhudhuk saka Anatolia dipanggonaké ing kono; penaklukan iku uga dadi alesan persekutuan Salib gedhé sing bakal pungkasané ing Lepanto.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Kekalahan Lepanto", "6a1d44a9"], "d": ["Armada Salib sing manunggal sawisé penaklukan Siprus nyekel armada Utsmaniyah ing Teluk Lepanto lan ngrusak perangan gedhéné; laksamana agung (kaptan-ı deryâ) Müezzinzade Ali Pasya gugur syahid, mung eskadroné Uluç Ali sing slamet. Sawisé bilai iku, Wazir Agung Sokollu Mehmed Pasya ngangkat Uluç Ali Pasya dadi laksamana agung kanthi tugas nglumpukaké armada sing buyar, lan miwiti mbangun armada anyar ing kabeh galangan kapal saka Istanbul nganti Alanya; nanging unggul mutlak ing Segara Tengah wis goyah sacara psikologis.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Perang Mezőkeresztes", "da308ec5"], "d": ["Ing perang papan jembar paling gedhé ing Perang Dawa (1593–1606), wadyabala sing dipimpin dhéwé déning Mehmed III, nalika wis arep buyar, pulih manèh amarga piwulangé Hoca Sadeddin Efendi banjur mbubaraké wadyabala Habsburg. Perang iki dianggep perang klasik gedhé pungkasan sing dimenangaké Utsmaniyah; nanging amarga ora ngowahi lakuné perang sacara umum, iku uga dianggep tandha ausé sistem militèr.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Prajanjèn Zsitvatorok", "39c01142"], "d": ["Liwat prajanjèn sing mungkasi perang ngentèkaké tenaga telulas taun, panguwasa Habsburg kanggo kaping pisan dianggep padha drajat karo sultan kanthi sebutan 'Kaisar Romawi' lan upeti taunan dibusak. Kelangan wilayah mèh ora ana; nanging owahé basa diplomasi iki diwaca minangka lambang pungkasané pengaku Utsmaniyah bab unggul mutlak ngadhepi Éropah.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Prajanjèn Qasr-i Shirin", "c1acf3af"], "d": ["Prajanjèn sing ditandhatangani sawisé Murad IV ngrebut manèh Baghdad (1638) mungkasi perang Utsmaniyah-Safawiyah sing luwih saka satus taun. Baghdad lan Irak tetep mesthi ing Utsmaniyah, Revan dipasrahaké marang Safawiyah; garis sing digambar, kanthi owah-owahan cilik, dadi dhasar tapel wates Turki-Iran saiki lan dianggep salah siji tapel wates sing paling dawa umuré ing donya. Prajanjèn iku masrahaké Bedre, Cessan, Mendeli, Derteng lan Derne marang Utsmaniyah; Bèntèng Zencir ing tapel wates kudu dirubuhaké, désa-désa ing kulonané dadi duwèké Utsmaniyah, sing ing wétané dadi duwèké Iran. Sakiwa-tengené Bèntèng Zalim cedhak Shahrizor lan Kızılca Kale tetep ing Utsmaniyah, Avroman lan Mihriban ing Iran; bèntèng Kotur, Mâkû lan Mağazberd bakal dirubuhaké déning kaloro pihak.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Penaklukan Kréta rampung", "e0d85604"], "d": ["Pengepungan Candia, babak pungkasan perang Kréta sing diwiwiti ing taun 1645, rampung amarga operasi mantep telung taun saka Fazil Ahmed Pasya; komandan Venesia, Morosini, masrahaké kutha iku liwat prajanjèn. Perjuangan sing lumaku kira-kira seprapat abad iku kacathet minangka pengepungan paling dawa ing sejarah Utsmaniyah; bèntèng Latin gedhé pungkasan ing Segara Tengah Wétan uga mlebu pamaréntahan Utsmaniyah. Telung bèntèng karang cilik ing pesisir lor pulo — Suda, Spinalonga lan Grambousa — isih tetep ing Venesia; amarga diadegaké ing pulo-pulo cilik sing kapisah, bèntèng-bèntèng iku ora bisa dituduhaké ing peta kapisah saka sisa Kréta.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Prajanjèn Buchach — tapel wates paling amba", "b17b6e5a"], "d": ["Kanthi Prajanjèn Buchach, sing ditandhatangani sawisé penaklukan Kamianets ing ekspedisi Polandia, Podolia digabungaké menyang Utsmaniyah lan sapérangan Ukraina dijupuk ing sangisoré pangayoman. Kanthi mangkono kekaisaran tekan tapel watesé sing paling amba ing Éropah; titik iki dianggep pucuk lan uga mata rantai pungkasan jaman ékspansi.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Bubrahé Pengepungan Wina II", "7d889252"], "d": ["Pengepungan Wina déning Merzifonlu Kara Mustafa Pasya sing lumaku rong sasi dadi bubrah amarga gebugan dumadakan sing diturunaké raja Polandia Jan Sobieski saka gumuk Kahlenberg; wadyabala mundur kanthi ninggalaké bekalané, lan Merzifonlu diukum pati ing Beograd. Perang karo Liga Suci sing dibentuk sawisé kamenangan iku lumaku 16 taun; bubrah iki dituduhaké minangka wiwitané kemunduran gedhé ing sejarah Utsmaniyah.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Penaklukan Bèntèng Grambousa — salah siji bèntèng karang Kréta sing isih ing Venesia", "3ddf9eeb"], "d": ["Senajan penaklukan Kréta dianggep wis akèh-akèhé rampung kanthi nyerahé Candia ing taun 1669, pulo-bèntèng karang Grambousa ing pucuk lor-kulon pulo isih ana ing tangané Venesia telulikur taun manèh. Kanthi direbuté ing taun 1692, salah siji saka telung sisa Venesia ing Kréta diresiki; déné Suda lan Spinalonga ngentèni ekspedisi Morea taun 1715.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Prajanjèn Karlowitz — kelangan wilayah gedhé kapisan", "8f7e2546"], "d": ["Liwat Karlowitz, sing mungkasi perang Liga Suci nem belas taun, Hongaria lan Transilvania dipasrahaké marang Austria, Podolia marang Polandia, Morea lan pesisir Dalmasia marang Venesia. Kanggo kaping pisan ing sejarah Utsmaniyah, wilayah sak gedhé iki ucul ing meja rembugan lan kanggo salawasé; prajanjèn iku dianggep dokumèn wiwitan jaman anyar nalika kekaisaran pindhah dadi bertahan ngadhepi Éropah, lan uga dadi titik owah-owahan ing sejarah diplomasi Utsmaniyah. Pamukiman sing ing dina sing padha ganti tangan ing atlas: Kostajnica lan Jasenovac (saka Utsmaniyah menyang Habsburg; teks prajanjèn nglilakaké Castanoviz ing tangané kaisar, dina penyerahané Jasenovac ora ana ing sumber, ditulis dina prajanjèn) lan Preveza (saka Venesia menyang Utsmaniyah; TDV karlofca: miturut katetepan sing ditandhatangani 24 Rajab 1110 / 26 Januari 1699, panggonan sing didhudhuki Venesia ing sisih lor Teluk Lepanto dibalèkaké). Atlas uga nulis Kostajnica lan Jasenovac ing sisih Habsburg, Uman lan Vinnytsia ing Ukraina Pinggir Tengen saka Utsmaniyah menyang Polandia (TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia: kakuwasaan Turki 1672-99) lan Nadin ing Dalmasia menyang Venesia (dina penyerahan sing khusus kanggo pamukiman iku ora ana ing sumber, ditulis dina prajanjèn; pucuk-pucuk periode Nadin durung diverifikasi karo sumber — perkiraan sing wis diumumaké). Vonitsa ing sisih lor Teluk Lepanto uga dibalèkaké saka Venesia menyang Utsmaniyah (TDV karlofca); ing Dalmasia Vrana (Urana) klebu panggonan sing tetep ing Venesia (pucuk periode durung diverifikasi — wis diumumaké).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["Kamenangan Prut", "2583572f"], "d": ["Ing perang sing muncul amarga prakara raja Swédia sing ngungsi menyang Utsmaniyah sawisé kekalahan Poltava, wadyabala Tsar Peter I dikepung ing pinggir Kali Prut lan kepeksa nyerah. Liwat prajanjèn sing ditandhatangani, Azak direbut manèh; déné keputusan ora ngrusak wadyabala lan mbébasaké tsar kacathet ing sejarah minangka keputusan sing nganti saiki isih dadi rembugan.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Penaklukan bèntèng Suda lan Spinalonga — ilangé tilas pungkasan Venesia ing Kréta", "7261f7ba"], "d": ["Telulikur taun sawisé tibané Grambousa ing taun 1692, liwat cabang sisih saka ekspedisi Morea, Suda lan Spinalonga, loro benteng pungkasan Venesia ing Kréta, uga ditaklukaké. Kanthi mangkono penaklukan Kréta sing diwiwiti ing taun 1645 rampung nganti sak jengkal pungkasan pulo ing pungkasané patang puluh enem taun.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Pambrontakan Patrona Halil", "100941a4"], "d": ["Gagalé ing front Iran, pajeg lan nesuné marang kamewahan kalangan kraton dadi pambrontakan gedhé sing dipimpin Patrona Halil, tukang ngladèni ing pemandhian. Wazir Agung Ibrahim Pasya dipatèni, Ahmed III dilèngsèraké lan Jaman Tulip rampung; para pambrontak sing nguwasani kutha pirang-pirang sasi nuduhaké kanthi cetha ringkihé panguwasa pusat.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Prajanjèn Beograd — Beograd, Smederevo lan Serbia lor direbut manèh", "ba7f8e46"], "d": ["Ing pungkasané perang ing rong front (1736–1739) nglawan Austria lan Rusia, Beograd lan Serbia Lor direbut manèh; Rusia sarujuk nglucuti gegaman Azak lan ora nduwèni armada ing Segara Ireng. Prajanjèn iku, sing dianggep suksès gedhé pungkasan diplomasi lan wadyabala Utsmaniyah abad ka-18, menehi kekaisaran mangsa tentrem seprapat abad. Pamukiman liya sing ing dina sing padha bali saka Austria menyang Utsmaniyah ing atlas: Hisarcık (Grocka) (ranté pusat-induk Beograd; TDV belgrad), Craiova, Râmnicu Vâlcea lan Turnu Severin (baliné Wallachia Cilik menyang Utsmaniyah, minangka bawahan Wallachia). Déné Bosanski Brod lan Bosanska Dubica ing jalur Sava ing atlas bali menyang Utsmaniyah tanggal 28 September 1739 (TDV bosna-hersek; TDV mahmud-i--osmanli: 28 September 1739). Târgu Jiu ing Wallachia Cilik uga bali menyang Utsmaniyah ing dina sing padha.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["Serangan Çeşme", "840b30bd"], "d": ["Armada Rusia sing mlebu Segara Tengah kanthi dhukungan Inggris nyerang armada Utsmaniyah ing plabuhan Çeşme, papan pangungsené, nganggo kapal geni lan ngobong mèh kabeh. Rusia kanggo kaping pisan muncul minangka kakuwatan laut gedhé ing Segara Tengah; bilai iku dadi salah siji gebugan sing nemtokaké nasibé perang tumuju Küçük Kaynarca taun 1774, lan nuduhaké kanthi cetha perluné reformasi dhasar armada.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Prajanjèn Küçük Kaynarca", "2776dcdb"], "d": ["Liwat Küçük Kaynarca, sing mungkasi perang 1768–1774 lan dianggep salah siji prajanjèn paling abot ing sejarah Utsmaniyah, Kasultanan (Khanat) Krimea diwènèhi 'kamardikan' — sejatiné kagawé wewengkon pengaruh Rusia. Rusia manggon ing pesisir Segara Ireng, oleh hak liwat Selat kanggo kapal dagang lan kedutaan tetep ing Istanbul; klausul pangayoman sing ora cetha marang kawula Ortodoks mbukak lawang kanggo alesan campur tangan ing abad sabanjuré. Kanggo kaping pisan tanah sing rakyaté Muslim dicopot saka kakuwasaan Utsmaniyah.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Panggabungan Krimea menyang Rusia", "bdf6faa8"], "d": ["Krimea 'mardika' sing digawé Küçük Kaynarca, kanthi alesan kekisruhan ing mangsa khan pungkasan, Şahin Giray, digabungaké menyang Rusia liwat manifèsto Katerina II. Kerja bareng Utsmaniyah-Krimea sing wis telung abad rampung; kelangan stèp lor ngilangaké jeroné pertahanan Istanbul lan miwiti gelombang gedhé kapisan migrasi puluhan èwu wong Tatar Krimea menyang wilayah Utsmaniyah. Ing dina iki semenanjung Krimea (Alushta, Kefe/Kaffa, Sudak, Yalta, Balaklava, Inkerman, Mangup, Arabat) mlebu Rusia; Taman lan Kuban uga pindhah menyang Rusia ing panggabungan sing padha (TDV Kırım: 8 April 1783 Julian = 19 April Gregorian).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["Selim III lan Nizam-i Cedid", "d53aec21"], "d": ["Selim III, sing munggah tahta ing tengah perang, weruh yen kekalahan-kekalahan iku sipaté struktural, banjur miwiti program reformasi jembar kanthi jeneng 'Nizam-i Cedid' (Tatanan Anyar): wadyabala anyar sing dilatih cara Éropah, kas kapisah sing mbandhani (Irad-i Cedid), nguwataké sekolah teknik, lan kedutaan tetep kapisan ing ibu kutha-ibu kutha Éropah. Program iku dianggep wiwitan tradhisi reformasi Turki modhèrn; nanging amarga perlawanan korps-korps lan para ayan (tokoh provinsi), bakal digulingaké ing taun 1807.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Dipungkasiné para Ksatria Malta — panggonan mampiré armada Prancis ing dalan", "d62f901d"], "d": ["Armada Prancis sing tumuju Mesir mampir ing Malta sing ana ing dalané; para Ksatria Santo Yohanes (Malta) masrahaké pulo iku tanpa akèh perlawanan. Kanthi mangkono rampung bèntèng pungkasan ordho ksatria sing diusir saka Rodhos ing taun 1522 lan banjur manggon ing kene. Rong taun sabanjuré Malta bakal tiba ing tangané Inggris, déné Napoleon saka pulo iku langsung tumuju Iskandariyah.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Pendhudhukan Mesir déning Napoleon", "93fede5f"], "d": ["Wadyabala Jenderal Bonaparte ndharat ing Iskandariyah lan ndhudhuki Mesir; ekspedisi iki, sing ngincer dalan Inggris menyang India, minangka serangan langsung kapisan saka kakuwatan Éropah marang tanah pusat Utsmaniyah. Serangan Nelson ing Abukir lan pertahanan Akko déning Cezzar Ahmed Pasya medhotaké lakuné Prancis; pendhudhukan rampung ing taun 1801, nanging ing kekosongan sing ditinggalaké diwiwiti munggahé Mehmed Ali Pasya saka Kavala lan jaman 'Prakara Wétan'.", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Sened-i Ittifak (Akta Persekutuan)", "cce49ef5"], "d": ["Dokumèn sing ditandhatangani antarané kraton lan kulawarga-kulawarga ayan sing kuwat ing dhaérah, dipimpin Alemdar Mustafa Pasya, ayan Rusçuk sing ndadèkaké Mahmud II munggah tahta; para ayan saguh setya marang sultan lan menehi pitulungan prajurit, déné nagara ngakoni anané lan hak-haké. Amarga iki conto kapisan ing sejarah Utsmaniyah nalika kakuwasaané sultan diwatesi nganggo dokumèn, sawetara sejarawan nganggepé wiwitan adoh saka tradhisi konstitusi; sejatiné ora ana daya manèh sajrone sawetara sasi.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["Pambrontakan Yunani diwiwiti", "a7293715"], "d": ["Pambrontakan sing disiapaké organisasi Filiki Eteria mbledhos dhisik ing Wallachia, banjur kanthi kakuwatan utama ing Morea; nagara, sing sibuk karo prakara Ali Pasya saka Tepelena, kasèp ing tumindak kapisan. Amarga rasa simpati gedhé marang Yunani (filhelenisme) ing panemuné masarakat Éropah, pambrontakan iku cepet dadi prakara internasional; kanthi mangkono sumbu gerakan kamardikan kapisan sing kasil ing jaman nasionalisme ing tanah Utsmaniyah disumet. Pamukiman liya sing ucul ing tanggal sing padha: Athena, Patras (Balyabadra), Thebes, Livadeia, Eleusis (Attika), Missolonghi.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["Pambrontakan bersenjata kapisan ing Morea", "77e6250f"], "d": ["Sawisé nyabrang Prut, pambrontakan mlumpat menyang Morea: tumindak bersenjata sing diwiwiti ing Kalavryta (21 Maret Julian) disusul gerakan ing Patras, Kalamata lan Mani; ora suwe Morea dadi pambrontakan umum lan pamaréntahan Utsmaniyah kelangan sapérangan gedhé semenanjung. Pamukiman liya sing ucul ing tanggal sing padha: Athena, Patras (Balyabadra), Thebes, Livadeia, Eleusis (Attika), Missolonghi.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["Vaka-i Hayriyye — Korps Yenisari dibubaraké", "08c9372a"], "d": ["Para yenisari, sing mbalikaké kuali minangka tandha mbrontak nglawan latihan Korps Eşkinci sing lagi diadegaké, ditumpes ing baraké ing Etmeydanı déning tembakan mriyem pasukan setya sing wis disiapaké Mahmud II; korps iku dibubaraké bebarengan karo kabeh cabangé lan pondhok tarékat Bektashi sing gegandhengan. Operasi iki, sing kacathet ing sejarah kanthi jeneng sing tegesé 'Kedadéan sing Becik', kanthi nyingkiraké lembaga sing umuré patang abad mbukak dalan kanggo wadyabala Asakir-i Mansure-i Muhammediyye lan kabeh reformasi pemusatan sabanjuré.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Serangan Navarino", "ee579e7f"], "d": ["Armada Utsmaniyah-Mesir, sing lagi madhemaké pambrontakan Yunani, diobong ing Navarino déning armada gabungan Inggris-Prancis-Rusia sing mlebu plabuhan tanpa ngumumaké perang; kira-kira sèket sewidak kapal lan èwuan pelaut ilang. Serangan iku, sing ing diplomasi Éropah diliwati kanthi sebutan 'kedadéan sing ora bejo', sejatiné njamin kamardikan Yunani lan mbukak dalan kanggo perang Utsmaniyah-Rusia 1828–29.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Maklumat Tanzimat", "5042ce7b"], "d": ["Liwat Hatt-i Humayun sing diwaca ing Gülhane, keamanan nyawa, bandha lan kehormatan kabeh kawula tanpa mbédakaké agama dijamin nagara; prinsip keadilan pajeg, tatanan wajib militèr lan ora ngukum tanpa pengadilan diumumaké. Maklumat iku, karyané Mustafa Reşid Pasya, dianggep dokumèn gedhé kapisan modhernisasi Utsmaniyah sing sipaté konstitusional lan menehi jeneng marang 'Jaman Tanzimat' (1839–1876), jaman reformasi; penataan manèh sing jero ing pamaréntahan, kukum, pendhidhikan lan keuangan ditindakaké ing kerangka iki.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Perang Krimea diwiwiti", "3b9ca3c8"], "d": ["Krisis sing diwiwiti amarga prakara panggonan-panggonan suci lan pengaku Rusia bab pangayoman marang kawula Ortodoks dadi paprangan terang-terangan sawisé Utsmaniyah ngumumaké perang; sawisé serangan Sinop, Inggris lan Prancis (banjur Piedmont) mèlu perang ing pihak Utsmaniyah. Kanthi wadyabala Sekutu ndharat ing Krimea lan ngrebut Sevastopol, perang dimenangaké liwat Prajanjèn Paris 1856; nanging utang manca kapisan sing dijupuk ing taun-taun perang (1854) nglebokaké kekaisaran ing pusaran ketergantungan keuangan sing bakal lumaku setengah abad.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Maklumat Reformasi (Islahat Fermanı)", "78ff234d"], "d": ["Maklumat sing diumumaké sadurungé rembugan tentrem Paris ngambakaké prinsip-prinsip Tanzimat lan menehi kawula non-Muslim hak padha sing amba, kalebu dadi pegawé nagara, dadi prajurit lan mbukak sekolah; organisasi jamaah ditata manèh. Liwat Prajanjèn Paris sing ditandhatangani sabanjuré, Nagara Utsmaniyah resmi ditampa ing kulawarga kukum antarnagara Éropah lan wutuhé wilayah dijamin bebarengan déning nagara-nagara gedhé — jaminan iki, ing prakteké, bakal dadi lawang anyar kanggo campur tangan.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Kanun-i Esasi — Jaman Konstitusi I", "0fe052c1"], "d": ["Ing dina bukaané konferènsi internasional sing kumpul ing Istanbul kanggo ngrembug krisis Balkan, konstitusi Utsmaniyah kapisan diumumaké kanthi tembakan mriyem; liwat Kanun-i Esasi, karya gerakan 'Utsmaniyah Anyar' sing dipimpin Midhat Pasya, diadegaké parlemèn rong kamar. Meclis-i Meb'usan dibukak ing Maret 1877; nanging Abdülhamid II, kanthi alesan Perang '93, ing Februari 1878 nglèrènaké parlemèn tanpa wates, lan konstitusi digantung suwéné telung puluh taun.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["Perang '93 (Perang Utsmaniyah-Rusia 1877–78)", "5bd96af7"], "d": ["Ing perang sing disebut 'Perang '93' amarga cocog karo taun Rumi 1293, wadyabala Rusia nyerang saka rong front; senajan pertahanan Plevna déning Gazi Osman Pasya lan paprangan Kaukasus Ahmed Muhtar Pasya dadi crita kepahlawanan, front iku ambruk lan wong Rusia maju nganti Yeşilköy (San Stefano). Perang iku miwiti gelombang gedhé migrasi Muslim saka Balkan lan Kaukasus tumuju Istanbul, sing akibaté isih krasa nganti saiki; struktur dhémografi lan keuangan kekaisaran ora bisa bali manèh kaya sadurungé.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Prajanjèn Berlin", "47f76a49"], "d": ["Kongres Berlin, sing ngrevisi 'Bulgaria Gedhé' sing digawé San Stefano atas jeneng imbangané nagara-nagara gedhé, tetep ninggalaké gambaran sing abot: Serbia, Montenegro lan Rumania dadi mardika; Kapangéranan Bulgaria otonom diadegaké; Bosnia-Hercegovina dipasrahaké marang pendhudhukan Austria, Siprus marang pamaréntahan Inggris, Kars-Ardahan-Batum marang Rusia. Tatanan Utsmaniyah sing umuré limang atus taun ing Rumelia akèh-akèhé bubrah; 'prakara Wétan' dadi agenda tetep diplomasi Éropah. Pamukiman liya sing ucul ing tanggal sing padha: Plovdiv, Vidin, Tarnovo, Varna, Shumen, Silistra, Ruse, Bukares, Iași, Constanța. Rumania, minangka gantiné nyerahaké Bessarabia marang Rusia, nampa Tulcea lan Dobruja: Tulcea, Babadag, Măcin, Isaccea, Hârșova lan Mangalia ing Dobruja Lor pindhah menyang Rumania.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["Pendhudhukan Tunisia lan Administrasi Utang Umum Utsmaniyah", "c7e25598"], "d": ["Prancis, kanthi alesan kedadéan ing tapel wates Aljazair, ndhudhuki Tunisia lan liwat Prajanjèn Bardo njupuk ing sangisoré pangayomané; anané Utsmaniyah ing Afrika Lor dadi mung Tripolitania. Liwat Dekret Muharram sing diwetokaké ing taun sing padha, kanggo ngurus utang manca sing bangkrut diadegaké Administrasi Utang Umum (Duyun-i Umumiyye), sing para kreditur diwakili ing njeroné: pamasukan pokok kaya uyah, mbako lan sutra langsung digandhèngaké karo administrasi manca iki lan kedaulatan keuangan diwatesi banget. Pamukiman liya sing ucul ing tanggal sing padha: Kairouan, Gabès, Sfax, Djerba.", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Pendhudhukan Inggris ing Mesir", "f1269768"], "d": ["Gerakan Urabi Pasya, sing muncul ing Mesir nglawan kebangkrutan keuangan lan kontrol manca, diremuk déning kamenangan Tel el-Kebir wadyabala Inggris sing ndharat sawisé Iskandariyah dibom, lan Kairo didhudhuki. Senajan sacara kukum Mesir tetep manut marang Utsmaniyah, sejatiné mlebu pamaréntahan Inggris; kontrol Terusan Suez manggon ing tengahé strategi kekaisaran Britania.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Pengumuman Jaman Konstitusi II", "95ee2fd2"], "d": ["Ngadhepi gerakan sing saya gedhé amarga para perwira anggota Komite Persatuan lan Kemajuan munggah gunung ing Makedonia, Abdülhamid II nglakokaké manèh Kanun-i Esasi; 'pengumuman kamardikan' ditampa kanthi gembira lan pemilu dianakaké. Nanging stabilitas ora teka: sawisé Kedadéan 31 Maret (April 1909) dipadhemaké, Abdülhamid dilèngsèraké; kamardikan Bulgaria, panggabungan Bosnia lan Kréta sing nyedhak menyang Yunani uga kedadéan ing sasi-sasi sing gonjang-ganjing iki.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Perang Tripolitania", "ed441994"], "d": ["Italia, sing lagi golek tanah jajahan, ngumumaké perang marang Tripolitania, tanah pungkasan Utsmaniyah ing Afrika Lor, lan ndhudhuki pesisiré; amarga nagara sing ora duwé armada ora bisa ngirim wadyabala reguler, para perwira enom kaya Mustafa Kemal lan Enver Bey kanthi dhelik-dhelik nyabrang menyang tlatah iku lan nata perlawanan sing èfèktif bebarengan karo suku-suku Senussi. Liwat Prajanjèn Ouchy sing ditandhatangani amarga mbledhosé Perang Balkan (18 Oktober 1912), Libia dipasrahaké marang Italia; Italia uga ndhudhuki Rodhos lan Dodekanesa.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Prajanjèn London — kelangan Rumelia", "f3f976df"], "d": ["Liwat Prajanjèn London sing mungkasi Perang Balkan I, kabeh tanah ing kulon garis Midye-Enez lan pulo-pulo Aegea ilang; Albania dadi mardika. Saka Rumelia, sing luwih saka limang atus taun dadi pusat bobot dhémografi, ékonomi lan budaya kekaisaran, mung Trakia Wétan sing bakal kari (Edirne direbut manèh ing Perang Balkan II); kelangan iku ndadèkaké kawicaksanan perang lan pamapanan pamaréntahan Ittihad dadi luwih keras sacara jero. Panggonan-panggonan ing kulon garis Midye-Enez sing ucul: Skopje, Veles, Štip, Strumica, Doiran, Gevgelija, Manastir, Ohrid, Debar (Dibra), Prizren, Pristina, Peć, Novi Pazar, Kosovo Polje; Serres, Drama, Kavala, Petrich, Nevrokop, Xanthi, Komotini, Dedeağaç, Didymoteicho, Çirmen, Feres, Soufli, Orestiada (Kumçiftliği), Praviște (Eleftheroupoli), Stérna, Távri, Umur Fakih (Fakia), Malak Dervent (Lalkovo); ing Kréta Chania, Candia, Rethymno, Sitia lan Sfakia.", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["Mlebu Perang Donya I", "05a0252e"], "d": ["Kapal perang Goeben lan Breslau, sing mlayu saka Inggris, dilebokaké liwat Selat kanthi digawé kaya wis dituku, narik nagara sethithik mbaka sethithik menyang pihak Jerman; perang sejatiné diwiwiti nalika armada sing dipimpin Laksamana Souchon ngebom plabuhan-plabuhan Rusia (29 Oktober), lan pengumuman perang saka kaloro pihak teka ing awal November. Senajan Jihad Agung (Cihad-i Ekber) diumumaké, pengaruh sing diarep-arep ora muncul; sajrone patang taun kekaisaran mlebu perang kanggo urip ing limang front sing béda, saka Kaukasus nganti Palestina.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Kamenangan Çanakkale", "95d888e8"], "d": ["Armada Sekutu, sing arep ngrubuhaké Istanbul lan tekan Rusia, ing 18 Maret dipukul mundur saka Selat déning tembakan garis ranjau lan bèntèng; garis ranjau sing dipasang kapal ranjau Nusret nemtokaké nasibé perang. Operasi dharatan Gallipoli sing diwiwiti ing April uga diendheg ing Anafartalar lan Conkbayırı; Sekutu ngosongaké semenanjung iku kabeh ing Januari 1916. Jenengé Letnan Kolonel Mustafa Kemal misuwur ing front iki; kamenangan sing dimenangaké kanthi kira-kira seprapat yuta syuhada lan korban dianggep minangka papan laire kader lan semangaté Perjuangan Nasional.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Pambrontakan Syarif Husain", "75f7c58c"], "d": ["Amir Mekah Syarif Husain, sawisé surat-suratan rahasia karo Inggris, mbrontak kanthi janji krajan Arab sing mardika; sepur Hijaz dadi sasaran serangan. Senajan pertahanan Madinah sing misuwur déning Fahreddin Pasya, sing lumaku nganti sawisé gencatan senjata, tetep dadi lambang perlawanan, pambrontakan iku, bebarengan karo majuné Inggris ing front Palestina, nyepetaké bubrahé kakuwasaan Utsmaniyah ing provinsi-provinsi Arab. Pamukiman liya sing ucul ing tanggal sing padha: Hurma, Turaba.", "f7c6b3e9"]},
"OLAYLAR:1918-10-30:0":{"b": ["Gencatan Senjata Mudros", "9e87c767"], "d": ["Nagara Utsmaniyah, sing front-fronté pedhot siji lan sijiné amarga ambruké Bulgaria, mundur saka perang liwat gencatan senjata sing ditandhatangani ing kapal perang Agamemnon. Dibukaké Selat lan utamané Pasal 7, sing ngidinaké ndhudhuki panggonan sing keamanané kaancam, ora suwe didadèkaké sarung kukum kanggo pambagèan sing nyata: Mosul, Iskandarun, banjur Izmir lan Istanbul didhudhuki. Gencatan senjata iku dianggep dokumèn pungkasané kekaisaran sacara nyata. Pamukiman liya sing ucul ing tanggal sing padha: Hama, Damaskus, Homs.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Mustafa Kemal ing Samsun — Perjuangan Nasional", "09a8f784"], "d": ["Ing swasana nesu amarga pendhudhukan Izmir, Mustafa Kemal Pasya, sing ndharat ing Samsun minangka inspektur Wadyabala IX, ngowahi tugas resminé dadi nata perlawanan ing Anatolia. Surat Edaran Amasya sarta kongres Erzurum lan Sivas minangka terusané tumindak iku; prinsip 'kamardikané bangsa bakal dislametaké déning tekad lan keputusané bangsa dhéwé' dadi inti program politik Perjuangan Nasional.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["Bukaané Majelis Agung Nasional (TBMM) lan Sèvres", "2008feec"], "d": ["Amarga Istanbul didhudhuki sacara resmi lan Meclis-i Meb'usan dibubaraké, ing 23 April 1920 Majelis Agung Nasional dibukak ing Ankara; majelis sing nglumpukaké wewenang luar biasa ing awaké dhéwé dadi inti nagara anyar sing adhedhasar karsané bangsa. Prajanjèn Sèvres sing ditandhatangani pamaréntah Istanbul ing Agustus mbagi-bagi Anatolia; TBMM ngumumaké sing nandhatangani prajanjèn iku pengkhianat tanah air, lan Sèvres ora tau bisa ditindakaké.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Perang Sakarya", "f2f970a6"], "d": ["Serangan Yunani, sing wis nyedhak nganti 50 kilomèter saka Ankara, dipecah ing perang 22 dina 22 bengi sing ditindakaké miturut dhawuhé Mustafa Kemal Pasya, sing wis nampa wewenang panglima tertinggi: 'Ora ana garis pertahanan, sing ana bidang pertahanan.' Wadyabala Yunani kanggo kaping pisan pindhah menyang pertahanan stratégis; kamenangan iku nggawa gelar Gazi lan pangkat marsekal (müşir) kanggo Mustafa Kemal, lan mbukak lawang kanggo Persetujuan Ankara karo Prancis sarta pangakuan saka njaba.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Serangan Gedhé lan kamardikané Izmir", "172a50c4"], "d": ["Serangan sing diwiwiti saka Kocatepe ing ésuk 26 Agustus tekan ditumpesé pasukan utama Yunani ing 30 Agustus ing Dumlupınar liwat Perang Panglima Tertinggi; ing pangoyakan sing diterusaké kanthi dhawuh 'Para wadyabala, tujuan kapisan kowé yaiku Segara Tengah, maju!', Izmir dimardikakaké ing 9 September. Liwat Gencatan Senjata Mudanya (11 Oktober) Trakia Wétan direbut manèh tanpa perang; kamenangan militèr iku nemtokaké kakuwatan nagara anyar sing bakal diadegaké ing Lausanne ing meja rembugan.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Dibusaké kasultanan", "9f36a9f6"], "d": ["Amarga pamaréntah Istanbul uga diundang menyang rembugan Lausanne, TBMM ing 1 November 1922 misahaké kasultanan saka khilafah lan mbusak kasultanan; pamaréntahan wangsa Utsmaniyah sing umuré 623 taun rampung sacara kukum. Mehmed VI Vahideddin ninggalaké nagara ing 17 November numpak kapal perang Inggris; Abdülmecid Efendi diangkat ing kalungguhan khalifah miturut keputusan TBMM, lan kalungguhan iku uga bakal dibusak ing 3 Maret 1924.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Prajanjèn Lausanne", "38c27f7d"], "d": ["Liwat Prajanjèn Tentrem Lausanne, sing ditandhatangani ing pungkasané rembugan abot wolung sasi, tapel wates, kamardikan kebak lan kedaulatan nagara Turki anyar diakoni sacara internasional; kapitulasi dibusak, Administrasi Utang Umum dilebokaké ing prosès likuidasi, lan ijol-ijolan pendhudhuk diatur. Lausanne, sing sejatiné mbatalaké Sèvres, dianggep kamenangan diplomasi Perjuangan Nasional lan dokumèn njaba sing ngadegaké Republik.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Pengumuman Republik", "d5bfcdfb"], "d": ["Republik diumumaké nalika TBMM, liwat owah-owahan konstitusi, nampa katetepan yen 'wujud pamaréntahan Nagara Turki iku republik'; Mustafa Kemal Pasya kapilih dadi presidhèn kapisan. Kanthi mangkono lelampahan Utsmaniyah 624 taun, sing diwiwiti ing 1299 minangka kadipaten tapel wates, ditutup, lan nagara anyar sing kedaulatané tanpa syarat kagungané bangsa diadegaké ing ndhuwur warisan kekaisaran.", "f5cabb8c"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Prajurit Albania nggulingaké gubernur Mesir", "c76a0ec2"], "d": ["Pasukan Albania sing ulufe (gajihé) ora dibayar mbrontak lan meksa gubernur Husrev Pasya mlayu saka bètèng. Ing kekosongan sing tuwuh amarga mundure wong Prancis, para bey Mamluk, korps Albania, lan para gubernur sing diangkat déning Porte Agung mlebu ing perjuangan telung pojok; Mehmed Ali dadi misuwur kanthi ngatur kasetimbangan ing segitiga iki. Papan liyané sing ucul ing tanggal sing padha: Thaif.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Ulama Kairo ngumumaké Mehmed Ali dadi gubernur", "a16752f2"], "d": ["Para pedagang lan ulama Kairo sing kabotan déning tekanan pajeg, dipimpin naqib al-asyraf Umar Makram, mbrontak, nyatakaké ora ngakoni gubernur Hurşid Pasya, lan nglungguhaké Mehmed Ali ing kalungguhan gubernur. Ing sajarah Utsmaniyah, gubernur sing dipilih déning rakyat iku prastawa sing arang banget ana tandhingané.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["Porte Agung nampa kasunyatan sing wis kelakon: firman gubernur Mesir", "b86736a3"], "d": ["Porte Agung, sing ora duwé kakuwatan kanggo njejegaké calone dhéwé ing Mesir, ngirim firman gubernur Mesir marang Mehmed Ali kanthi pangkat wazir. Ing peta, wiwit tanggal iki Mesir pindhah menyang lapisan bawahan (werna enom): sacara hukum tlatah Utsmaniyah, nanging kasunyatané negarané wangsa Kavalalı. Papan liyané sing pindhah menyang lapisan bawahan ing tanggal sing padha: Kairo, Iskandariyah, Damietta, Asyut, Aswan, Ibrim, Suez, Reşîd (Rosetta).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["Ekspedisi Inggris Fraser ndharat ing Iskandariyah", "4d6c31be"], "d": ["Minangka wangsulan marang Utsmaniyah sing nyedhak menyang Prancis, Inggris ngirim pasukan pendharatan menyang Mesir. Nalika iku Mehmed Ali lagi ngadhepi para Mamluk ing Mesir Hulu; dhèwèké énggal bali lan nata pertahanan.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Kakalahan ing Reşid (Rosetta) — Inggris dipukul mundur", "3636004c"], "d": ["Barisan Inggris sing mlebu kutha cilik Reşid nandhang karugèn abot ing perang dalan; ing sasi September pasukan kuwi ninggalaké Mesir kabèh. Kamenangan iki ngukuhaké wibawané Mehmed Ali, ing Mesir uga ing Istanbul.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Prastawa Bètèng: panumpesan para bey Mamluk", "84030b97"], "d": ["Para bey Mamluk sing diundang menyang arak-arakan upacara kanggo ekspedisi Hijaz kejebak ing lorong ciyut Bètèng Kairo lan ditumpes. Kanthi mangkono pengaruh Mamluk sing wis limang abad rampung, lan Mehmed Ali ora duwé saingan manèh ing Mesir.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Ekspedisi Hijaz diwiwiti — wadyabala maju menyang Yanbu liwat segara saka Suez lan liwat dharatan ing dalan kaji", "1c05c159"], "d": ["Ngrebut manèh Haramain, sing wiwit taun 1803 ana ing pamaréntahan Saudi-Wahabi, iku prakara legitimasi paling gedhé tumrap Mahmud II; amarga kakuwatan Porte Agung ora nyukupi, tugas iku dipasrahaké marang gubernur Mesir. Mehmed Ali ngutus putrané sing umur nem belas taun, Tosun, dadi pangarepé wadyabala.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Yanbu ditampa nyerah — pangkalan pesisir kapisan ing ekspedisi Hijaz", "179bc78d"], "d": ["Watara rong èwu prajurit infantri Albania, sing mangkat saka Suez nganggo kapal-kapal sing anyar digawé, ndharat cedhak Yanbu ing Oktober 1811; kutha cilik iku nyerah sawisé nglawan kanthi lemah suwéné rong dina. Pasukan jaranan ing pangwasané Tosun ngetutaké dalan kaji liwat dharatan lan lagi tekan Yanbu rong minggu sawisé, ngliwati Aqaba lan al-Wajh. Yanbu dadi pangkalan kapisan ing Hijaz tumrap wadyabala Mesir sing bakal maju menyang Madinah lan Makkah.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Kakalahan kapisan ing selat gunung Safra-Jadida", "99ef804d"], "d": ["Pasukan pangarep Mesir sing dicegat ing lorong-lorong gunung sing ciyut dadi buyar. Kakalahan iki dadi piwulang taktik ing ekspedisi kasebut: dimangertèni manawa maju ing Hijaz ora bisa tanpa panyengkuyung suku-suku Badui.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Madinah direbut manèh", "6f6a5d55"], "d": ["Sawisé dikepung suwé, Madinah nyerah. Direbuté manèh kuthané Kanjeng Nabi dirayakaké ing Istanbul kanthi pésta tembakan mriyem; minangka ganjaran, Mehmed Ali uga diparingi kalungguhan gubernur Jeddah.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["Makkah direbut manèh — dalan kaji kabukak", "3d6d66a0"], "d": ["Pasukan Mesir sing mlebu Makkah ndadèkaké khutbah ing Ka'bah diwaca manèh atas asmané sultan Utsmaniyah. Kafilah kaji sing wis sepuluh taun kepedhot bisa mangkat manèh. Ing peta, Hijaz bali menyang pangwasa Utsmaniyah, nanging amarga pamaréntahané ana ing Kairo, ditampilaké nganggo werna bawahan. Papan liyané sing pindhah menyang pamaréntahan bawahan ing tanggal sing padha: Jeddah.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Direbuté manèh Thaif — rampungé ekspedisi Hijaz", "6315fb31"], "d": ["Sawisé Madinah (Desember 1812) lan Makkah (Januari 1813), wadyabala Mesir ing pangwasané Tosun Pasya pungkasané ngrebut manèh Thaif saka wong Wahabi. Pangwasa Saudi sing suwéné sepuluh taun rampung, lan telu pusat suci ing Hijaz bali ana ing pangawasan Utsmaniyah-Mesir.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Mehmed Ali dhéwé tindak menyang Hijaz", "fda0ea2d"], "d": ["Weruh ekspedisi mlaku alon, gubernur iku njupuk pamaréntahan langsung ing tangané; kanthi tawar-tinawar karo para pangarsa suku, dhèwèké nyoba ngudhari garis ngarep Saudi saka njero. Bagéané Mesir ing dagang Segara Abang uga tambah gedhé amarga ekspedisi iki.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Perang Bisel: pasukan Saudi dikalahaké mutlak", "9c9ab91f"], "d": ["Wong Saudi sing kalah abot ing perang ara-ara mundur menyang tlatah pedalaman. Gencatan senjata sing digawé ora langgeng; rong taun sawisé, operasi bakal digawa menyang jantung Najd. Sawisé kamenangan iki, atlas nganggep Turaba lan Hurma ing sisih wétan Thaif wis ucul saka tangan Saudi (sumber prastawa Lorimer, Gazetteer; kasaksèn mligi tumrap papan-papan kuwi lan tanggal 13 Januari iku kira-kira sing wis diterangaké).", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["Ibrahim Pasya mangkat ing ekspedisi Najd", "d5ed80d1"], "d": ["Ibrahim Pasya, sing nampa komando sawisé sedané sadulure, Tosun, miwiti lelampahan abot ing ara-ara samun suwéné rong taun. Wadyabala sing maju saka sumur siji menyang sumur sijiné, karo nyingkiraké suku-suku siji mbaka siji, pungkasané tekan ing ngarep kutha krajan Saudi.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Diriyah tiba — Nagara Saudi Kapisan rampung", "aa96206d"], "d": ["Sawisé dikepung suwéné nem sasi, Diriyah nyerah lan dirusak. Emir Abdullah bin Saud dikirim menyang Istanbul lan diukum pati. Kanggo sepisanan, gendéra Utsmaniyah tekan semono jeroné ing pedalaman Arab; garnisun Najd tetep ana nganti taun 1824. Papan liyané sing gabung ing tanggal sing padha: Diriyah (Najd).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Ekspedisi Sudan diwiwiti", "b1fc6905"], "d": ["Tujuané Mehmed Ali ana telu: nglumpukaké prajurit kanggo wadyabalané, ngranggèh emas Sennar, lan numpes sisa-sisa Mamluk sing mlayu. Pasukan ing pangwasané putrané, İsmail Pasya, mudhun ngidul ngetutaké Kali Nil.", "478563e9"]},
"OLAYLAR_EK4:1820-11-01:0":{"b": ["Dongola pindhah menyang wadyabala Mesir tanpa kekerasan (para Mamluk wis ninggalaké ing Juni 1820)", "bc5942c0"], "d": ["Dongola ing tikungan gedhé Kali Nil, sawisé ditinggal para Mamluk ing Juni 1820, tiba ing tangané wadyabala Mesir sing dipimpin İsmail Pasya tanpa kekerasan. Ing peta, wiwit tanggal iki Sudan katon ing lapisan bawahan: sing nelukaké iku Kairo, lan sing bakal mréntah uga Kairo.", "61ac03d6"]},
"OLAYLAR_EK4:1820-12-04:0":{"b": ["Perang Jabal al-Dayqa — konfederasi Syayqiya dikalahaké mutlak déning wadyabala Mesir", "befc9539"], "d": ["Sasasi sawisé tempuran kapisan ing Kurti, wadyabalané İsmail Pasya, putrané Muhammad Ali Pasya, ngalahaké Syayqiya ing perang kapindho sing nemtokaké cedhak Jabal al-Dayqa. Pangarsa Syayqiya, Makk Subayr, nyerah; Makk Syawisy terus nglawan. Wiwit iku pangwasa Mesir ing tikungan Kali Nil dadi tetep.", "5e0734a7"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["Kasultanan Sennar (Funj) nyerah", "3cac7dd2"], "d": ["Wangsa Funj sing wis telung abad nyerah tanpa perang. Pakémahan sing diadegaké ing taun sing padha ing papan patemoné rong cabang Kali Nil énggal dadi Khartoum, pusat pamaréntahan Sudan. Papan liyané sing gabung ing tanggal sing padha: Sennar.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Kordofan direbut", "06440602"], "d": ["Barisan kapindho sing dikirim mangulon ngalahaké pasukan Darfur ing Bara (Bâra) lan ngrebut Kordofan bebarengan karo tlatah sakiwa-tengené Nuhud. Kanthi mangkono pangwasa Mesir ing Sudan jembar saka lembah Nil menyang stépa sisih kulon.", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Pasukan Mesir ndharat ing Kreta", "835aee90"], "d": ["Nalika pambrontakan Yunani nular menyang Kreta, Porte Agung njaluk supaya pasukan Mesir dikirim menyang pulo iku. Pengaruhé Mehmed Ali ing pulo kuwi diwiwiti saka campur tangan iki, lan wolung taun sawisé dipungkasi kanthi diparingaké kalungguhan gubernur Kreta marang dhèwèké.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["İsmail Pasya dipatèni ing Shendi", "223860c9"], "d": ["Emir lokal Nimr, sing nesu amarga panjaluk pajeg abot lan prajurit, ngobong omah sing dienggoni İsmail Pasya nginep, nganti İsmail Pasya sakpandhèrèké kobong. Ekspedisi piwales ndadèkaké tlatah iku banjir getih; wiwit iku pamaréntahan Sudan diadegaké adhedhasar kekerasan.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Mahmud II njaluk pitulung marang Mehmed Ali kanggo Morea", "03594a42"], "d": ["Kanggo pambrontakan Morea sing sajroné telung taun ora bisa ditumpes déning wadyabala Janissari, sultan nyuwun pitulung marang wadyabala Mesir sing dilatih cara Éropah. Minangka piwales, dijanjèkaké kalungguhan gubernur Morea lan Kreta. Panjaluk iki dadi pangakuan terbuka kapisan manawa kakaisaran wis gumantung marang provinsiné dhéwé.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["Ibrahim Pasya ndharat ing Modon", "9c993dba"], "d": ["Pasukan pendharatan sing direksa déning armada Mesir ngancik pucuk kidul-kulon Morea. Wadyabala iki, sing nduwé infantri reguler (nizami) lan artileri lapangan, kanthi cepet unggul ngadhepi gerombolan pambrontak.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Tripolitsa direbut manèh — puseré Morea tiba", "8a478c11"], "d": ["Kanthi tibané Tripolitsa, pusat pamaréntahan pambrontakan, pérangan gedhé Morea bali ana ing pangawasan. Ing peta, semenanjung iku katon nganggo werna bawahan amarga ana ing tangané pasukan Mesir.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Missolonghi (Mesolongi) tiba", "07257f87"], "d": ["Sawisé dikepung suwéné setaun, kutha iku direbut. Nanging kumandhangé pertahanan kutha kuwi ing koran-koran Éropah njunjung simpati marang perjuangan Yunani nganti pucuké lan nyawisaké dalan kanggo campur tangané nagara-nagara gedhé.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["Akropolis Athena ditampa nyerah", "3b19f946"], "d": ["Kanthi tibané Akropolis, pambrontakan Yunani sacara militèr meh rampung. Pas ing titik iki, prakara kuwi ora manèh dadi pambrontakan njero nagara, nanging dadi bab diplomasi Éropah.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Prajanjian London: telung nagara meksakaké otonomi Yunani", "7ce46fd8"], "d": ["Inggris, Prancis, lan Rusia mutusaké tumindak bebarengan supaya Utsmaniyah lan wong Yunani nampa gencatan senjata lan sarat otonomi; diumumaké yèn tawaran iku ditolak, armadané bakal campur tangan. Porte Agung nolak usulan kasebut.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Prajanjian Iskandariyah: keputusané Mesir mundur saka Morea", "cc978f37"], "d": ["Mehmed Ali, sing kélangan armadané ing Navarino, rembugan langsung karo laksamana Inggris tanpa takon marang Istanbul lan sarujuk narik pasukané saka Morea. Gubernur sing gawé prajanjian dhéwé karo nagara-nagara gedhé iku dadi pratandha krisis sing bakal teka.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Pasukan Mesir ninggalaké Morea", "8fb742dd"], "d": ["Pasukan pungkasan diunggahaké menyang kapal; semenanjung iku kasunyatané ucul saka tangan lan, miturut Protokol London 1830, dadi intiné Yunani sing mardika. Mehmed Ali dhéwé ora nampa kalungguhan gubernur Morea sing dijanjèkaké, malah kélangan armada lan wadyabala sing gedhé. Papan liyané sing ucul ing tanggal sing padha: Modon, Koron.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["Pamaréntahan Kreta dipasrahaké marang Mehmed Ali", "7f76396d"], "d": ["Minangka ganti ruginé kélangan Morea, kalungguhan gubernur Kreta diparingaké marang Mehmed Ali. Pulo iku diprentah saka Kairo suwéné sepuluh taun; ing peta, sajroné wektu iki katon nganggo werna bawahan. Papan liyané sing gabung ing tanggal sing padha: Candia (Kreta).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["Ibrahim Pasya mlebu Suriah — krisis kapisan diwiwiti", "1a5cc386"], "d": ["Alesan lahiré yaiku gubernur Akko sing ora gelem mbalèkaké para fellah sing mlayu saka Mesir; sebab sing sejati yaiku kabutuhané Mehmed Ali marang kayu, plabuhan, lan tenaga manungsa saka Suriah. Wadyabala nyabrang Sinai lan cepet ngrebut pesisir Palestina.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Pengepungan Akko diwiwiti", "b211d96d"], "d": ["Bètèng sing ngendheg Napoleon ing taun 1799 iku nglawan suwéné nem sasi. Pengepungan iki dadi ujian gedhé kapisan tumrap artileri modèren wadyabala Mesir.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Akko tiba", "0f47917b"], "d": ["Nalika batere mriyem sing nggebugi témbok gawé jebolan, bètèng iku direbut. Gapurané Suriah wis menga; ing dina-dina kuwi uga, Porte Agung nyatakaké Mehmed Ali dadi pambrontak lan nyopot kalungguhané minangka gubernur.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Damaskus nyerah", "48da3b62"], "d": ["Kutha iku nyerah tanpa perang. Ibrahim Pasya nyoba ngranggèh panyengkuyung warga lokal kanthi ngumumaké tatanan pajeg lan kasetaraan sing diparingaké marang wong non-Muslim; kawicaksanan sing padha kuwi sawetara taun sawisé uga bakal dadi sebabé pambrontakan nglawan dhèwèké. Papan liyané sing gabung ing dina-dina kuwi: Beirut, Tripoli Syam, Sidon.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Perang Homs", "867810ee"], "d": ["Wadyabala Utsmaniyah sing dikirim kanggo nylametaké Suriah dikalahaké mutlak ing ara-ara. Katon yèn wadyabala anyar, sing diadegaké nem taun sawisé Janissari dibubaraké, durung siyaga.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Aleppo direbut", "9c0ead76"], "d": ["Pusat dagang lan pamaréntahan Suriah sisih lor uga tiba. Kanthi mangkono wadyabala Mesir tekan sikilé Pagunungan Taurus lan nuju menyang lorong-lorong ing gapurané Anatolia.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Kakalahan ing Lorong Belen (Beylan) — Çukurova kabukak", "4bae872b"], "d": ["Garis pertahanan dijebol ing lorong ciyut Pagunungan Amanos. Antiokhia, Adana, lan Tarsus pindhah menyang pasukan Mesir (dhudhukan Maraş, miturut TDV, dumadi ing 1833, dadi butir kapisah); ing peta Çukurova malih dadi werna bawahan. Dalan menyang pedalaman Anatolia saiki ora ana sing njaga.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Lorong Gülek tiba — pesisir İçil (Mersin, Silifke) mlebu pangawasan Mesir", "d9049b5b"], "d": ["Lorong Gülek, gapura Pagunungan Taurus menyang Çukurova, tiba ing tangané wadyabala Mesir. Ibrahim Pasya ngangkat mütesellimé dhéwé kanggo Sancak İçil, lan kabèh dhermaga ing pesisir mlebu pangawasan Mesir. Ing peta, Mersin lan Silifke ditampilaké dadi pérangané Mesir wiwit dina iki (wates ngisor; dina pangangkatan ora ana ing sumber); amarga ing keputusan Kütahya mung muhassıllık Adana sing dipasrahaké, pangawasan iki rampung bebarengan karo Anatolia dikosongaké.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Ereğli Konya didhudhuki Mesir — lawang Taurus ing dalan Konya–Adana", "fb908900"], "d": ["Ereğli, sing ana ing dalan menyang Konya tumrap wadyabala Mesir sing ngliwati Lorong Gülek, didhudhuki Ibrahim Pasya ing taun 1832, lan nalika dikosongaké miturut tatanan Kütahya 1833, bali digabungaké karo provinsi Karaman. Ing peta, papan iki dadi titik antara sing ana sumberé ing garis dhudhukan antarané Adana lan Konya; ora ditemokaké kasaksèn ing tingkat kutha kanggo Ulukışla lan Karapınar.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["Wadyabala Mesir mlebu Konya", "13952a2d"], "d": ["Wadyabala sing nyabrang Pagunungan Taurus tekan Anatolia Tengah. Sepisanan, pasukané gubernur Utsmaniyah maju ing tlatah inti kakaisaran. Papan liyané sing gabung ing tanggal sing padha: Karaman.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Perang Konya: wazir agung ditawan", "ec82cc9a"], "d": ["Wadyabala Utsmaniyah sing buyar ing hawa pedhut nandhang kakalahan abot, lan wazir agung Reşid Mehmed Pasya ditawan. Wadyabala pusat nagara wis ora ana manèh; ora ana kakuwatan sing isa ngadeg ing antarané Istanbul lan pasukan Mesir.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Maraş didhudhuki Mesir", "f558e383"], "d": ["Miturut TDV, ing taun 1833 Maraş didhudhuki déning Ibrahim Pasya Kavalalı lan tetep ana ing pamaréntahané meh sangalas sasi. Amarga Maraş ana ing sanjabané wates provinsi miturut tatanan Kütahya, pamaréntahan iki mung sacara kasunyatan, dudu sacara hukum.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Karahisâr-ı Sâhib (Afyon) didhudhuki Mesir — dalan Konya–Kütahya", "ae0c2c78"], "d": ["Karahisâr-ı Sâhib, sing ana ing dalané wadyabala Mesir nalika maju menyang Kütahya sawisé Perang Konya, ing taun 1833 sawetara wektu ana ing tangané Ibrahim Pasya. Ing peta, papan iki dadi titik antara sing ana sumberé ing garis dhudhukan antarané Konya lan Kütahya; ora ditemokaké kasaksèn ing tingkat kutha kanggo Akşehir, Ilgın, lan İshaklı, mula padha ana ing werna Utsmaniyah.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["Wadyabala Mesir tekan Kütahya", "214f8df6"], "d": ["Ibrahim Pasya mandheg ing Kütahya, sing adohé telung pos lelampahan saka Istanbul. Anggoné ora maju manèh iku alesan pulitik, dudu militèr: campur tangan Rusia lan réaksi Éropah wis diétung.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Armada Rusia ing ngarep Büyükdere", "6f836d61"], "d": ["Mahmud II, sing ora bisa éntuk pitulung saka Inggris lan Prancis, njaluk pitulung marang Rusia, mungsuhé wingi. Keputusan iki, sing dièlingi liwat tembungé sultan \"wong sing klelep ing segara bakal nyekel ula\", njalari prajurit Rusia ndharat ing Selat-Selat lan ngunèkaké lonceng tandha bebaya ing Éropah.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Kesepakatan Kütahya (lisan) — Suriah lan Adana kanggo Kavalalı", "25fe9985"], "d": ["Saliyané Mesir, Kreta, lan Hijaz, Porte Agung masrahaké kalungguhan gubernur Damaskus, Aleppo, Tripoli (Syam), lan Sidon marang Mehmed Ali; dene muhassıllık Adana marang İbrahim Pasya. Minangka gantiné, wadyabala mundur menyang sisih kidulé Pagunungan Taurus. Iki dudu prajanjian, nanging awujud firman sing diparingaké sultan marang gubernur — prakarané durung rampung, mung ditundha.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Munduré wadyabala Mesir saka Anatolia rampung liwat Gülek", "a53ac2a3"], "d": ["Sawisé tatanan Kütahya, pasukan Mesir ninggalaké Anatolia; nyedhaki tengah sasi Juni, kabèh wadyabala wis nyabrang saka Lorong Gülek menyang Çukurova. Pesisir İçil (Mersin, Silifke) bali menyang pamaréntahan Utsmaniyah; muhassıllık Adana lan Suriah tetep ana ing Mesir.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Prajanjian Hünkâr İskelesi", "da741d5c"], "d": ["Persekutuan pertahanan bebarengan suwéné wolung taun ditandhatangani karo Rusia. Miturut pasal wadi, yèn Rusia diserang, Utsmaniyah bakal nutup Selat-Selat tumrap kapal perang. Iki dadi salah siji keputusan diplomasi Utsmaniyah sing paling akèh dipadu lan ndadèkaké Inggris aktif ing prakara Mesir.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Pambrontakan Palestina-Nablus nglawan pamaréntahan Mesir", "4fe43e27"], "d": ["Wajib militèr, panglumpukan gaman, lan pajeg anyar njalari pambrontakan sing amba ing Palestina. Pambrontakan iku ditumpes kanthi keras; panyengkuyungé warga lokal marang pamaréntahan Mesir cepet luntur.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Pungkasané pamaréntahan Mesir ing Maraş (kira-kira)", "bb46ca42"], "d": ["Yèn ukara TDV bab suwéné 'meh sangalas sasi' diétung wiwit dhudhukan 1833, pamaréntahan Mesir rampung watara mangsa panas 1834. Mustafa Bey saka Küçükalioğulları, sing ing taun 1834 ora kuwat nglawan wadyabala Mesir lan mundur menyang arah Maraş, uga nuduhaké yèn nalika iku Maraş dadi papan pangungsèn ing sanjabané pangawasan Mesir.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Pambrontakan Jabal al-Druz", "12e74626"], "d": ["Perlawanan sing tuwuh ing tlatah Druz lumaku suwéné rong taun. Rasa ora marem sing nglumpuk ing Suriah, ing taun 1840, nalika armada sekutu ndharat ing pesisir, bakal ndadèkaké buriné wadyabala Mesir kothong tanpa pangayoman.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Mehmed Ali ngabaraké niyaté mardika", "48633bbd"], "d": ["Gubernur iku mratélakaké marang para konsul nagara gedhé yèn dhèwèké nimbang arep ngumumaké kamardikané Mesir lan Suriah. Inggris nolak kanthi tegas: laire nagara kuwat ing Segara Tengah sing cedhak karo Prancis bakal ngancam dalan menyang Hindia.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["Wadyabala Utsmaniyah nyabrang Kali Efrat", "9af1ea69"], "d": ["Mahmud II ngerahaké wadyabalané menyang tapel wates Suriah kanggo ngrebut manèh apa sing ilang ing Kütahya. Perwira Prusia Moltke, sing ana ing wadyabala minangka penasihat, mbantah pamilihé papan pertahanan lan serangan sing kesusu; bantahané ora digagas.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Perang Nizip — wadyabala Utsmaniyah buyar", "156b3cdf"], "d": ["Wadyabala Utsmaniyah sing diatur papané kanthi ala dikalahaké mutlak mung sajroné sawetara jam. Sultan séda sadurungé kabar kakalahan tekan Istanbul; sajroné sawetara dina, nagara bakal kélangan wadyabala, rajané, banjur armadané.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Sédané Mahmud II", "07eccfff"], "d": ["Sultan sing sajroné kuwasa telung puluh siji taun mbubaraké Janissari lan ngedegaké manèh pamaréntahan pusat iku séda tanpa bisa ngalahaké mungsuhé sing paling gedhé. Lelarané ora didiagnosis kanthi trep. Sédané didhelikaké nganti 30 Juni, nganti tindakan militèr dijupuk ing kutha amarga kuwatir manawa semangat Janissari bakal obah manèh.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Jumenengé Abdülmecid lan layon Mahmud II", "d0f3d2cc"], "d": ["Sawisé ramané séda, Abdülmecid sing umur nem belas taun jumeneng. Ing dina sing padha, layon Mahmud II digawa menyang Kraton Topkapı; karusuhan sing dikuwatiraké ora kedadéan, lan wong akèh, Muslim uga non-Muslim, mèlu arak-arakan layon.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Armada dipasrahaké ing Iskandariyah", "a53e6103"], "d": ["Kaptan-ı derya (laksamana agung) Ahmed Fevzi Pasya, sing nyujanani yèn wazir agung Koca Husrev Pasya bakal masrahaké armada marang Rusia, nggawa armada menyang Iskandariyah lan masrahaké marang Mehmed Ali. Ing sasi sing padha, Nagara Utsmaniyah tanpa wadyabala, tanpa sultan, lan tanpa armada.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Nota bebarengan saka nagara-nagara gedhé", "2a3b8316"], "d": ["Lima nagara ngaturaké nota marang Porte Agung supaya ora gawé sarujukan dhéwé ing prakara Mesir. Kanthi mangkono, prakara njero nagara resmi dadi \"prakara Éropah\"; nagara Utsmaniyah kasunyatané kélangan wewenang mutusaké bab provinsiné dhéwé.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Prajanjian London: patang nagara ing pihak Utsmaniyah", "a517f775"], "d": ["Prajanjian sing ditandhatangani kanthi ninggalaké Prancis iku menèhi ultimatum marang Mehmed Ali: yèn nampa sajroné sepuluh dina, éntuk kalungguhan gubernur Mesir turun-temurun lan Akko saumur urip; yèn sajroné rong puluh dina, mung Mesir; yèn nolak, ora éntuk apa-apa. Gubernur iku nolak.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Pamboman Beirut lan pendharatan sekutu", "0905ce92"], "d": ["Armada Inggris-Austria nembaki Beirut nganggo mriyem; gaman diedum marang rakyat sing mbrontak nglawan pamaréntahan Mesir ing pagunungan Libanon. Pangawasané Ibrahim Pasya ing Suriah ambruk, kejepit antarané pambrontakan njero lan campur tangan njaba.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Beirut lan kutha-kutha pesisir ucul saka tangan", "09bdaf23"], "d": ["Sawisé tempuran ing arah Baalbek, pasukan Mesir mundur saka pesisir. Ing peta, pesisir Libanon metu saka werna bawahan lan bali menyang pamaréntahan Utsmaniyah langsung.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Akko tiba sajroné rong jam", "5aec21f0"], "d": ["Ing pamboman armada sekutu, gudhang amunisi bètèng mbledhos lan Akko nyerah sajroné sawetara jam. Bètèng sing wolung taun sadurungé mung bisa direbut Ibrahim Pasya sajroné nem sasi iku nuduhaké unggulé artileri segara.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Konvènsi Iskandariyah", "85cb47b0"], "d": ["Mehmed Ali sarujuk ngeculaké Suriah, Adana, Kreta, lan Hijaz, mbalèkaké armada Utsmaniyah, lan ngakoni pangwasa sultan; minangka gantiné, kalungguhan gubernur Mesir sing turun-temurun dijamin.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["Wadyabala Mesir ninggalaké Suriah lan Çukurova", "719a28dc"], "d": ["Dhudhukan suwéné sangang taun rampung; wadyabala Ibrahim Pasya bali menyang Mesir liwat Sinai. Ing peta, sabuk amba sing mbentang saka Aleppo nganti Gaza lan saka Adana nganti Kreta bali menyang pamaréntahan Utsmaniyah langsung. Papan liyané sing ucul ing tanggal sing padha: Urfa, Maraş, Tarsus, Antiokhia, Candia (Kreta), Hama, Damaskus, Yerusalem, Jaffa, Nablus.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Firman: kalungguhan gubernur Mesir dipasrahaké turun-temurun marang kulawarga Kavalalı", "87b89ff8"], "d": ["Firmané sultan ngakoni kalungguhan gubernur lumintu saka bapak menyang anak ing njero wangsa; minangka gantiné, cacahé wadyabala dikurangi dadi wolulas èwu, pajeg diiket karo Istanbul, lan wewenang nyithak dhuwit sarta gawé prajanjian dicabut. Mesir tetep dadi provinsi, nanging saiki wis dadi negarané wangsa dhéwé. Pamaréntahan Hijaz lan Haramain bali menyang Porte Agung. Papan liyané sing bali saka lapisan bawahan menyang lapisan langsung ing tanggal sing padha: Makkah, Madinah, Jeddah, Yanbu.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Konvènsi Selat London", "0e95a1ea"], "d": ["Konvènsi sing ngganti Hünkâr İskelesi iki netepaké yèn ing jaman tentrem Selat-Selat katutup tumrap kabèh kapal perang. Kanthi mangkono hak mirunggan sing dimenangaké Rusia dhéwé malih dadi jaminan bebarengan Éropah; prakara Selat éntuk status internasional.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["Ibrahim Pasya kasunyatané dadi gubernur Mesir", "9e14f5d9"], "d": ["Ngganti Mehmed Ali sing saya sepuh lan kélangan kawarasan pikirané, putrané, Ibrahim Pasya, diangkat dadi gubernur. Nanging sawetara sasi sawisé, ing November 1848, dhèwèké séda ndhisiki ramané.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Sédané Kavalalı Mehmed Ali Pasya", "871310e0"], "d": ["Gubernur sing lair ing Kavala, ngedegaké wangsa ing Mesir, lan kaping pindho nggawa kakaisaran menyang pinggiré jurang iku séda ing umur wolung puluh taun. Wangsa sing diadegaké mréntah Mesir nganti taun 1953; nagara, sing weruh manawa tatu sing digawéné mung bisa ditutup kanthi campur tangan Éropah, banjur maju ing dalan Tanzimat.", "c0877894"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Sédané Ertuğrul Gazi lan jumenengé Osman Bey ing beylik — warisan Söğüt lan Domaniç", "395fb9fa"], "d": ["Miturut TDV, Ertuğrul Gazi séda ing taun 680 (1281-82); butir kasebut nyathet yèn tanggal 1288 lan 1289 uga disebutaké. Saka ramané, Osman Bey ora marisi kutha sing wis ditelukaké, nanging rong paringan sing diwènèhaké sultan Seljuk marang Ertuğrul, sing dipapanaké ing garis paling ngarep tlatah tapel watesé: papan mangsa adhem (yurtluk) ing Söğüt lan pangonan mangsa panas (yaylak) ing Domaniç. Tegesé, beylik iku miwiti uripé ora nganggo warisan penaklukan, nanging nganggo rong paringan pangonan; ing peta, rong papan iki ditampilaké minangka 'warisan', dudu 'penaklukan'.", "37fbc33c"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Serbuan menyang Kulacahisar — operasi militèr kapisané Osman Bey", "79b00b14"], "d": ["TDV, butir Osman I: 'Dhèwèké njarah lan ngobong Bètèng Kulaca sing cilik cedhak İnegöl (684/1285).' Iki tumindak militèr kapisané Osman Bey sing bisa ditemtokaké tanggalé ing sumber. Ora ana papan dunung sing direbut kanthi tetep; bètèng iku dijarah lan diobong, mula iki luwih pas diarani serbuan tapel wates klasik tinimbang penaklukan. Kedadéan iki dianggep titik wiwitané kagiyatan militèr beylik.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Direbuté Karacahisar — kutha kapisan sing diduwèni lan pangwasa marang Eskişehir", "178ae619"], "d": ["TDV, butir Osman I: ing taun 687 (1288) Osman Bey 'nelukaké Karacahisar lan dadi sing nguwasani Eskişehir'. Iki kutha sejati kapisan sing diduwèni beylik, lan miturut crita turun-temurun, amarga kasil iki Osman Bey munggah dadi sancak beyi ing tapel wates; dicritakaké yèn khutbah Jemuwah kapisan atas asmané diwaca ing Karacahisar lan kadi kapisan diangkat ing kono. Butir TDV Eskişehir nyathet yèn tradisi Utsmaniyah nyebut tanggal 1291, nanging benere isih diragokaké.", "90949e22"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Direbuté Bilecik lan Yarhisar kanthi serbuan wengi", "f461b0af"], "d": ["TDV, butir Bilecik: 'Sanajan para tekfur liyané ing tlatah iku, klebu tekfur Bilecik, nyusun rancangan arep matèni Osman Gazi, bareng rancangan iku kawruhan, pasukan Utsmaniyah nelukaké Yarhisar lan Bilecik kanthi serbuan dadakan (1299).' Rong bètèng iku direbut ing siji operasi, ing serbuan wengi sing padha. Tanggal iki dadi titik owah sing ditampa minangka taun adegé Nagara Utsmaniyah. Papan liyané sing gabung ing tanggal sing padha: İnegöl.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Perang Koyunhisar (Bapheus) — kamenangan gedhé kapisan nglawan wadyabala Bizantium", "584a9512"], "d": ["TDV, butir Osman I: tanggal 27 Juli 1302 Osman Bey perang lawan wadyabala Bizantium ing Bapheus (Koyunhisar) lan ngalahaké. Kamenangan iki dadi titik owah sing ngunggahaké Osman Bey saka mung pangarsa tapel wates dhaérah dadi pangadeg wangsa. Sawisé perang, dhataran Bursa mlebu pangawasan Utsmaniyah lan blokadé marang Iznik diwiwiti.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Kamenangan ing Dimbos lan sawisé iku direbuté Kite sarta Ulubat", "e168ab64"], "d": ["TDV, butir Osman I: ing taun 702 (1303) persekutuan sing diadegaké para tekfur Bursa, Kestel, Kite, lan Adranos dikalahaké ing lorong Dimbos; mungsuh dipeksa mundur karo perang nganti lorong sing ciyut, lan tekfur Kestel tiwas ing paprangan. Sanalika sawisé kamenangan, bètèng Kite lan Ulubat direbut, saéngga sesambungan dharatané Bursa pedhot lan blokadené saya kenceng. Orhan sing isih enom uga mèlu perang iki.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Ekspedisi Sakarya: direbuté Leblebicihisar, Lefke, Mekece, lan Geyve", "a51ba4d3"], "d": ["TDV, butir Osman I menèhi urut-urutané ekspedisi Sakarya taun 704 (1304): 'Nalika tekan Bètèng Leblebüci, tekfuré tundhuk... Dhèwèké tekan Lefke... Dhèwèké tekan Mekece... Dhèwèké menyang Geyve lan ngrebut bètèng sing ditemoni kothong.' Lefke iku gapurané lembah Sakarya sing menga menyang Bilecik. Ekspedisi siji iki, kanthi nglebokaké ranté bètèng sauruté lembah menyang pangawasan Utsmaniyah, nutup suwiwi wétan cekungan Iznik.", "ae2866c2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Direbuté bètèng-bètèng Lorong Geyve: Karaçepüş, Karatigin, lan Absu", "76907c78"], "d": ["TDV, butir Orhan: ing ekspedisi Sakarya taun 705 (1305), Orhan 'nelukaké bètèng Karaçepüş (Katoikia), Karatigin ing ngarep Iznik, lan Absu (Hypsu: ing Lorong Geyve)'. Telu bètèng iki, kanthi nutup liwatan antarané lembah Sakarya lan cekungan Iznik, medhot babar pisan pitulungan dharatan menyang Iznik. Gazi Abdurrahman dipapanaké ing Karaçepüş lan Absu ing lorong Geyve; saiki kutha iku mung bisa ditibakaké lumantar keluwèn.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Ekspedisi Adranos (Orhaneli) — ekspedisi pungkasané Osman Bey", "4811546c"], "d": ["TDV, butir Orhan nyathet ekspedisi menyang Bètèng Adranos ing mangsa gugur 1323 minangka ekspedisi pungkasané Osman Bey. Tekfur Adranos biyèn dadi anggota persekutuan tekfur sing diadegaké nglawan Utsmaniyah ing Dimbos rong puluh taun sadurungé; ekspedisi iki ateges nutup étungan lawas kuwi. Dina pasti direbuté bètèng ora dingertèni; operasi iki diterusaké déning Orhan Bey.", "1e8ea25a"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Perang Pelekanon (Maltepe) lan direbuté kabèh Kocaeli", "389e7bd4"], "d": ["TDV, butir Orhan: ing dina kapisan perang, Orhan Gazi ngirim pasukan telung atus wong kanggo mancing wadyabala Bizantium nyedhak; ing dina kapindho, perang dadi gedhé nalika pasukan ing pangwasané Pazarlu mudhun menyang dhataran, lan nalika kaisar tatu kena panah, wadyabala Bizantium dadi geger. Asilé cetha: 'Orhan ngrebut kabèh Kocaeli; sawisé kamenangan, wong Iznik wis ora duwé pangarep-arep.' Kutha-kutha pesisir saka Hereke nganti Üsküdar mlebu pamaréntahan Utsmaniyah, lan Gebze didadèkaké pusat tlatah. Iki wadyabala kekaisaran Bizantium pungkasan sing teka kanggo nylametaké Istanbul.", "73fe4332"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Bizantium kudu mbayar upeti — pengepungan İzmit lan prajanjian", "0c1ec8d3"], "d": ["TDV, butir Orhan: ing mangsa panas 733 (1333), Orhan ngepung İzmit nganggo wadyabala gedhé lan manjanik, lan kaisar gelem gawé prajanjian. Minangka gantiné Orhan ngendheg pengepungan, Bizantium sarujuk mbayar 12.000 dhuwit emas (hyperpyra) saben taun marang Orhan; 'kanthi mangkono, ing paningalé emir Utsmaniyah, Bizantium tiba ing kalungguhan nagara sing mbayar upeti'. Minangka timbal balik, Orhan bakal dadi kancané kaisar lan ora nyerang kutha-kutha bawahan Bizantium. Beylik tapel wates sing bisa meksa Romawi Wétan mbayar upeti iku dadi pangumuman sepira adohé imbangan kakuwatan wis malik.", "e2e3eeb4"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Panggabungan Beylik Karesi: Balıkesir, Bergama, Biga, Edremit, lan Erdek", "c7cb0511"], "d": ["TDV, butir Orhan (İnalcık) nempataké panggabungan iki ing taun 735 (1334-35): sawisé sedané Demirhan Bey, para gazi Karesi lan Hacı İlbey ngundang Dursun Bey menyang dhampar lan njaluk pitulungan marang Orhan. Orhan luwih dhisik maju menyang Balıkesir; nalika Dursun Bey, sing lunga rembugan tentrem, mati kena panah saka bètèng Bergama, beylik iku sakabèhé digabungaké karo tlatah Utsmaniyah. Ing operasi sing padha, Kirmasti lan Mihaliç tundhuk, Gölyazı direbut, lan Ulubat, sing sadurungé ditinggal kanthi jaminan kaslametan (eman), direbut kanthi tetep. Orhan ngangkat Süleyman Pasya ing sancak Karesi lan ndadèkaké Biga pusat tapel wates — kanthi mangkono kader pelaut kanggo nyabrang menyang Rumeli bisa diduwèni. Cathetan: butir TDV Karesioğulları nyebut taun 746 (1345) kanggo prastawa sing padha; ensiklopedi iku ora cocog karo awaké dhéwé. Papan liyané sing gabung ing tanggal sing padha: Çanakkale.", "f5ed82c2"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Timur ngrebut Herat: pungkasané wangsa Kart lan pindhahé Khurasan menyang Timuriyah", "15f6019e"], "d": ["Ing taun 1380, Khurasan pecah-belah amarga perebutan antarané Sarbadar, wangsa Kart, lan wangsa Muzaffariyah. Sawisé ngutus putrané, Miran Shah, menyang tlatah iku, Timur dhéwé maju menyang Herat lan, sawisé ngepung sawetara wektu, nampa kutha iku saka malik Kart, Ghiyath al-Din Pir Ali. Pambrontakan sing tuwuh sawisé dhèwèké lunga ditumpes kanthi banjir getih déning Miran Shah, lan wangsa Kart, sing mréntah ing Herat wiwit 1255, dipungkasi. Kabèh Khurasan, saka Mashhad nganti Nishapur, mlebu pamaréntahan Timuriyah ing tanggal iki.", "6ae06d43"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["'Ekspedisi Telung Taun' Timur: direbuté Azerbaijan lan Iran sisih lor", "2a98ec51"], "d": ["Timur, sing nalika ekspedisi Khurasan weruh saka cedhak kahanan Iran sing pecah-belah, maju mangulon ing taun 788 (1386). Ing operasi 1386-1388, sing kondhang minangka 'Ekspedisi Telung Taun', dhèwèké liwat Mazandaran, Luristan, lan Georgia mlebu Azerbaijan lan tekan Karabakh; Tabriz, Ardabil, Urmia, lan Nakhchivan mlebu pamaréntahan Timuriyah. Direbuté Iran sisih lor lan Azerbaijan uga dadi wiwitané padudon dawa karo Horde Emas, kaya sing biyèn dumadi antarané ulus Jochi lan wangsa Ilkhaniyah.", "aaf3b558"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Pungkasané wangsa Muzaffariyah: Shah Mansur kalah ing ngarep Shiraz", "5fd14eb8"], "d": ["Shah Mansur, panguwasa kuwat pungkasan saka wangsa Muzaffariyah sing wiwit 1318 mréntah ing Yazd, Fars, Isfahan, lan Kerman, sekutu karo sanak-sedulure lan obah nglawan Timur. Ing perang cedhak Shiraz, nalika salah siji emiré mbalik menyang pihak mungsuh, dhèwèké kélangan akèh-akèhé pasukané, kalah, lan dipatèni. Sawisé Timur uga matèni kabèh anggota wangsa, pangwasa Muzaffariyah rampung, lan Fars sarta Kerman digabungaké karo pamaréntahan Timuriyah.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Timur ngrebut Baghdad — wangsa Jalayiriyah mlayu menyang Anatolia", "4d5602b3"], "d": ["Timur ngrebut Baghdad sawisé ngepung suwé; panguwasa kutha iku, Sultan Ahmed saka Jalayiriyah, mlayu mangulon lan ngungsi dhisik menyang wangsa Mamluk, banjur menyang kraton Utsmaniyah. Kanthi mangkono jembaré Timur mangulon sepisanan sesambungan langsung karo laladan pengaruh Utsmaniyah. Mata ranté kapisan saka memungsuhan antarané rong panguwasa iku diwiwiti saka kéné.", "2fac674f"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Tantangané Timur: panjaluk mbalèkaké buronan ditolak", "33790bc8"], "d": ["Amarga ditekan Timur, Sultan Ahmed saka Jalayiriyah lan pangarsa Qaraqoyunlu, Qara Yusuf, ngungsi menyang tlatah Utsmaniyah; Timur njaluk supaya buronan loro iku dibalèkaké, lan Yıldırım Bayezid nolak. Banjur rong panguwasa iku wiwit ijol-ijolan layang sing isiné pangasoran abot saka loro-loroné. Dhasar idhéologi perang diadegaké lumantar surat-suratan iki, sadurungé ana siji prajurit waé sing obah.", "ac66be59"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Timur ngremuk Sivas nganti rata", "f4d79de6"], "d": ["Timur, sing maju menyang Sivas kanthi dituntun Qarayuluk Osman Bey saka Aqqoyunlu lan emir Erzincan, Mutahharten, ngepung kutha iku suwéné wolulas dina lan, sawisé nampa nyerahé kanthi janji ora bakal ana getih sapa waé sing diwutahaké, banjur nindakaké pambantaian gedhé; para pambela diuncalaké menyang paritan lan diurug urip-urip. Bangunan-bangunan wigati kutha, wiwit saka témbok bètèng, dirusak, lan Sivas ambruk sacara demografi. Iki gebugan gedhé kapisan sing ditibakaké Timur marang tlatah Utsmaniyah, rong taun sadurungé Perang Ankara.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Yıldırım Bayezid ngrebut manèh Erzincan lan Kemah", "7047ca08"], "d": ["Nggunakaké kalodhangan nalika Timur mangkat ing ekspedisi Suriah, Yıldırım Bayezid ngrebut Erzincan lan Kemah saka tangané emir Erzincan, Mutahharten, sing dadi bawahané Timur. Sanajan ora campur tangan nalika Sivas dirusak, tumindak iki ateges tantangan langsung marang laladan pengaruhé Timur ing Anatolia Wétan. Wiwit iku sesambungané rong panguwasa kuwi ora bisa didandani manèh.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Ultimatum saka Timur sing dikirim saka Tabriz — patang sarat", "3e1ac50e"], "d": ["Lumantar utusan sing dikirim saka Tabriz, Timur ngabaraké patang sarat: Kemah dibalèkaké marang Mutahharten, lemah sing dijupuk saka para bey Anatolia dibalèkaké marang sing duwé, siji pangéran Utsmaniyah dikirim dadi sandera sarta topi (külah) lan sabuk ditampa minangka tandha tundhuk, lan Qara Yusuf dipasrahaké. Bayezid ora nampa siji-sijia; sanajan para pangarsa nagara meksa lan Mutahharten dadi perantara, rembugan iku gagal. Timur wis mantep arep mungkasi prakara Anatolia kanthi cetha sadurungé mangkat ing ekspedisi menyang Cina.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Beylik Saruhanoğulları diadegaké manèh — Manisa ucul saka Utsmaniyah", "ac747b05"], "d": ["Telung minggu sawisé kakalahan ing Ankara, kanthi panyengkuyungé Timur, Orhan Bey dadi pangarsa beylik lan tlatah Saruhan mardika manèh. Tlatah sing puseré ing Manisa ilang saka peta rolas taun sawisé digabungaké karo Utsmaniyah ing taun 1390. Iki salah siji penerapan kapisan, sing tanggalé dingertèni kanthi cetha, saka pulitik Timur nguripaké manèh para beylik.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Emir Süleyman mlayu menyang Rumeli nggawa bandha nagara", "0a2b7363"], "d": ["Emir Süleyman, sing nggawa bandha nagara ing Bursa, arsip, kulawarga, lan sadulur-sadulure, nyabrang nganggo kapal saka Gemlik menyang Güzelcehisar (Anadoluhisarı), saka kono tekan Gallipoli lan ngumumaké pangwasané ing Edirne. Pamindhahé arsip lan bandha nagara menyang Rumeli iku wiwitané pusat abot Utsmaniyah geser menyang Balkan sajroné sak generasi. Ing peta, wiwit tanggal iki Rumeli digambar nganggo wernané Emir Süleyman dhéwé.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Timur ngadegaké manèh beylik-beylik Anatolia — manunggalé bangsa Turk pecah", "15187774"], "d": ["Sawisé menang ing Ankara, Timur mbalèkaké para bey sing ana ing sandhingé menyang tlatah lawasé. Mehmed Bey lan Ali Bey saka Karamanoğlu diparingi tlatah Karaman bebarengan karo Kayseri, Kırşehir, Sivrihisar, lan Beyşehir; Yakub Bey II saka Germiyanoğlu nampa Kütahya lan tlatah Germiyan; İsfendiyar Bey saka Candaroğlu nampa Çankırı lan Kalecik, minangka tambahan saka garis Kastamonu-Sinop. Tlatah Aydın, Menteşe, lan Teke uga bali menyang wangsa lawasé. Manunggalé Turk ing Anatolia sing dibangun Yıldırım Bayezid sajroné sepuluh taun pecah mung sajroné siji mangsa panas; ing peta, beylik-beylik iki katon manèh nganggo wernané dhéwé-dhéwé. Papan liyané sing ganti tangan ing proses sing padha: Aksaray, Denizli, Ereğli (Konya), Ermenek, Ilgın, Karapınar, Kayseri, Konya, Kırşehir, Kütahya, Sivrihisar, Söke.", "0c3d6fbf"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Timur ngrebut İzmir saka ksatria Santo Yohanes", "66dd1dd4"], "d": ["Timur, sing mudhun mangulon liwat Kütahya, Denizli, Aydın, Ayasuluk, lan Tire, ngepung lan ngrebut kutha pesisir İzmir, sing wiwit taun 1344 ana ing tangané wong Kristen. Sawisé kanthi cepet ngrebut bètèng iki, sing wis pirang-pirang taun ora bisa direbut Yıldırım Bayezid, lan uga ngrebut bètèng-bètèng sakiwa-tengené, Timur ninggalaké tlatah Aydın marang sing duwé lawasé lan bali mangétan. Sawisé iku kutha kuwi mlebu pamaréntahan Aydınoğlu Cüneyd Bey.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Isa Çelebi ngrebut Bursa — lair bagéan Anatolia", "955128c1"], "d": ["Isa Çelebi, sing sawisé kakalahan ing Ankara mundur menyang tlatah Karesi, ngrebut Bursa nalika Timur ana ing İzmir. Ing krajan lawas sing dijarah lan diobong prajurité Timur, dhèwèké ngumumaké pangwasané lan nyithak dhuwit atas asmané dhéwé; ing Januari 1403 ing Anatolia dhèwèké diakoni kanthi sesebutan 'panguwasa wong Turk'. Ing peta, bagéan iki, sing mbentang sauruté pesisir Asia Segara Marmara, katon nganggo wernané Isa Çelebi dhéwé.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Munduré Timur saka Anatolia", "93a98839"], "d": ["Nalika nampa kabar yèn Yıldırım Bayezid séda ing Akşehir, Timur nganggep urusané ing Anatolia wis rampung lan mangétan. Sing ditinggal yaiku para beylik sing wis nyatakaké setya marang dhèwèké lan para pangéran Utsmaniyah sing padha memungsuhan; sawetara kutha, kayata Sivas, dipasrahaké ing tangané emir bawahané Timur, kayata Mezid Bey. Timur ora tau bali manèh menyang Anatolia, nanging tatanan pecah-belah sing diadegaké lumaku suwéné sepuluh taun.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Emir Süleyman nyabrang menyang Anatolia: Bursa tiba ing tangané", "9b27aa5f"], "d": ["Krungu kakalahané Îsâ Çelebi, Emir Süleyman nyabrang menyang Anatolia bebarengan karo Çandarlı Ali Pasya kanthi wadyabala sing kuwat lan ngrebut Bursa; cathetan Maret 1404 nuduhaké yèn Karadeniz Ereğli uga ana ing pamaréntahané. Çelebi Mehmed ora kuwat nglawan Süleyman, sing énggal nguwasani Rumeli lan akèh-akèhé Anatolia. Papan liyané sing pindhah saka Çelebi Mehmed menyang Emir Süleyman ing proses sing padha: Akyazı, Anadolu Hisarı, Absu (Hypsu), Adranos (Orhaneli), Akhisar (Pamukova), Armutlu, Bètèng Aydos, Ayvalık, Balıkesir, Behramkale (Assos), Bergama, Beykoz, Biga. Ing peta, wiwit tanggal iki nganti Çelebi Mehmed ngrebut manèh Bursa (1410), pesisir loro iku katon nganggo siji werna, ing bagéané Emir Süleyman.", "0fc7e1b4"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Perang Dhataran Yenişehir — Çelebi Mehmed mundur menyang Amasya", "f1568288"], "d": ["Çelebi Mehmed, sing wis kélangan Bursa lan Ankara, dikalahaké Emir Süleyman ing dhataran Yenişehir, kélangan kabèh asil sing wis diranggèh ing Anatolia Kulon, lan mundur menyang pangkalané ing Tokat-Amasya. Sawisé kakalahan iki, dhèwèké ngéndhani tempuran langsung lan nguwataké wibawané ing pedalaman Anatolia. Kanthi mangkono diwiwiti babak sepi sing paling dawa ing Jaman Fetret.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Emir Süleyman ngrebut Ankara saka Çelebi Mehmed", "d6a2acd6"], "d": ["Ing taun 1406, Emir Süleyman ngepung Ankara, sing sawisé Timur mundur saka Anatolia tetep ana ing tangané Çelebi Mehmed. Panjaga bètèng, Yakub Bey, nahan sawetara wektu, nanging amarga akal-akalané wazir agung Çandarlı Ali Pasya, dhèwèké masrahaké bètèng marang Süleyman. Banjur Çelebi Mehmed sarujukan karo Mehmed Bey saka Karamanoğlu lan obah nglawan Süleyman.", "f2a18bf9"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Wiwitané pamaréntahan dey ing Aljir", "e99faa51"], "d": ["Ocak Aljir lan taife-i reis (golongan kapitan bajak laut) nyopot agha pungkasan lan milih Hacı Mehmed dadi dey saumur urip. Sawisé tanggal iki, Aljir diprentah dudu déning beylerbeyi sing diangkat Istanbul, nanging déning dey sing dipilih ocak lokal saka antarané anggotané dhéwé; sesambungan karo Utsmaniyah mung winates ing diwacané asmané sultan ing khutbah lan kuwajiban gendéra sarta mèlu ekspedisi. Kanthi mangkono Aljir malih saka provinsi dadi ocaklık — owah-owahan sing padha dialami Tunis ing 1705 karo wangsa Husainiyah lan Tripolitania ing 1711 karo wangsa Karamanli.", "b8decd95"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Direbuté Köprühisar lan persiapan adegé Yenişehir", "39abff03"], "d": ["Kanthi ngrubuhaké bèntèng-bèntèng dalan liwat antarané Bursa lan Iznik, dipasang dhasar markas ngarep sing bakal ngepung kutha loro iku.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Adegé Yenişehir", "d3275837"], "d": ["Pamukiman-garnisun Utsmaniyah kapisan sing tumata diadegaké kanggo mimpin pengepungan Bursa lan Iznik; Orhan Ghazi miyos ing kene.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Pengepungan kapisan Iznik lan penaklukan Marmaracık", "cdca2349"], "d": ["Iznik dikepung kanggo kaping pisan nanging ora bisa dirubuhaké (penaklukan pungkasan ing 1331); bèntèng Marmaracık sing cedhak direbut ing wektu iki.", "31c4c65f"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Köse Mihal mlebu Islam lan gabung karo Utsmaniyah", "ca0d86e1"], "d": ["Tekfur Harmankaya, Köse Mihal, mlebu Islam lan gabung karo Osman Ghazi bebarengan karo bèntèng lan wong-wongé; panjenengané dadi komandan Utsmaniyah kapisan sing asalé saka Bizantium.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan Bey njupuk pamaréntahan sacara nyata", "6dadbefc"], "d": ["Amarga Osman Ghazi wis sepuh lan lara, pimpinan lan pangelolaan pengepungan Bursa lan ekspedisi sacara nyata pindhah menyang putrané, Orhan Bey (munggah tahtané sacara resmi ing taun 1326).", "280c6e0d"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Akyazı lan Pulo İmralı pindhah menyang tangané Utsmaniyah (tanggal ora ana ing sumber)", "380c60ce"], "d": ["Akyazı dadi sasaran serangan Utsmaniyah ing jaman Osman Bey (ing taun-taun sawisé ekspedisi 1305); taun direbuté sing mesthi ora dimangertèni. Ora ana sumber siji waé sing nyebut kapan Pulo İmralı direbut. Tapel wates taun 1324 ing peta mung pangisi sauntara.", "69782c1e"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akça Koca nguwasani Kandıra lan sakiwa-tengené", "341bb97e"], "d": ["Akça Koca, salah siji panguwasa tapel watesé Orhan Ghazi, nalika nyerang tlatah Izmit saka markasé ing kulon Tlaga Sapanca, udakara taun 1326 ngrebut Kandıra lan sakiwa-tengené. Izmit isih ana ing tangané Bizantium; kutha iku lagi bakal tiba ing taun 1337.", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["Gabungé Yalova lan Karamürsel", "133cb07a"], "d": ["Taun iki Yalova lan sakiwa-tengené ing pesisir kidul Teluk Izmit tiba ing tangané wong Turki; jalur pesisir diparingaké déning Orhan Bey minangka timar marang Karamürsel Gazi.", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akça Koca ngrebut Aydos lan bètèng Samandıra", "ce4daa8a"], "d": ["Sawisé Kandıra direbut, Akça Koca, bebarengan karo Konuralp lan Gazi Abdurrahman, ngrebut bèntèng Aydos cedhak Kartal, banjur bèntèng Samandıra ing sisih loré; tlatah Samandıra diparingaké marang panjenengané minangka duwèké. Akça Koca séda cedhak Kandıra ing taun 1328; panguwasa tapel wates tlatah iku diparingaké marang Pangeran Murad.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Persekutuan Utsmaniyah-Aydın-Saruhan", "9df6bb74"], "d": ["Telung kadipaten tumindak bebarengan nglawan Bizantium; armadané Umur Bey saka Aydın, kanthi serangané marang pesisir Trakia, ngentèkaké tenaga Bizantium ing front kapindho.", "32ca49ea"]},
"OLAYLAR_EK:1334-01-01:0":{"b": ["Penaklukan Gemlik (Kios)", "66fc4bcd"], "d": ["Kutha pesisir Gemlik (Kios) ing Teluk Gemlik, sing mbukak menyang Segara Marmara, pindhah menyang tangané Utsmaniyah. Nalika Bursa nyerah ing taun 1326, tekfur kutha iku dikirim menyang Gemlik bebarengan karo kulawargané; tegesé ing taun 1326 Gemlik isih ana ing tangané Bizantium. Ora ketemu tanggal kapisah kanggo Armutlu; Armutlu digandhèngaké karo ranté Gemlik.", "27ef02f4"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Direbuté Ankara", "49bf1f6d"], "d": ["Ankara sing dipimpin wong Ahi mlebu pamaréntahan Utsmaniyah; dalan menyang Anatolia Tengah kabukak. Panggonan liya sing digabungake ing tanggal sing padha: Sivrihisar, Çankırı.", "eec5d13e"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Dipedhoté dalan pitulungan Edirne: bèntèng Çorlu, Lüleburgaz, Babaeski lan Keşan", "8e8ad485"], "d": ["Pangeran Murad, sing miwiti manèh gerakan penaklukan sawisé Halil dislametaké, ngirim para penyerang (akıncı) nganti ngarep Istanbul supaya Edirne kapisah saka pitulungan sing bisa teka saka njaba. Bèntèng Çorlu, Lüleburgaz lan Babaeski ing dalan Istanbul-Edirne lan Keşan ing simpang dalan Trakia Kidul direbut. Penyerahan Edirne teka sawisé bunderan pengepungan iki rampung.", "fb171002"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Perang Çirmen — kontrol lembah Maritsa", "cd738d8d"], "d": ["Wadyabalané para bey Serbia dibubaraké ing serangan wengi; para bey lokal Serbia lan Bulgaria ing Makedonia lan Rhodope siji mbaka siji wiwit mbayar upeti marang Utsmaniyah — dudu penaklukan langsung, nanging wiwitan gelombang dadi bawahan. Ing riwayat Utsmaniyah perang iki uga dicritakaké kanthi jeneng 'Sırpsındığı' lan taun 1364, minangka serangan wengi Hacı İlbey marang wadyabala Salib sing teka kanggo ngrebut manèh Edirne; TDV nyatakaké yen tanggal iku salah lan crita loro iku babagan perang sing padha.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Penaklukan Plovdiv lan Stara Zagora", "e780c9ae"], "d": ["Plovdiv, ing sisih ndhuwur lembah Maritsa, lan Stara Zagora ing sisih loré direbut; Ketsaran Bulgaria dadi nagara sing mbayar upeti. Dalan Tatar Pazardzhik lan Ihtiman antarané Plovdiv lan Sofia tetep ana ing tangané para bey lokal sing dadi bawahan sawisé Çirmen. Pamukiman liya sing ucul ing tanggal sing padha: Haskovo, Klokotnitsa.", "019bac28"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Penaklukan Serres", "d4d28b60"], "d": ["Serres, kunci Makedonia Wétan, direbut; Thessaloniki mlebu ing bunderan pengepungan. Jalur Kyustendil-Petrich-Nevrokop-Drama antarané Sofia lan Serres ing tanggal iki durung digabungaké langsung; sacara gilir, ing antarané taun 1370-an nganti 1383 dadi bawahan, sawisé 1383 pindhah menyang pamaréntahan langsung. Pamukiman liya sing ucul ing tanggal sing padha: Gevgelija, Kilkis (Avrathisar).", "69be987a"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Penaklukan Sofia", "96d5f01f"], "d": ["Dalan liwat sisih kulon pagunungan Balkan dikontrol; amarga ing tanggal iki Serres wis dicekel wiwit 1383, tanah Trakia lan Makedonia dadi siji wutuh tanpa pedhot.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Penaklukan Niš", "77f5d632"], "d": ["Kanthi direbuté Niš, kunci lembah Morava, Despotat Serbia kaancam langsung.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Penyerahan kapisan Thessaloniki", "96010ee9"], "d": ["Sawisé blokade dawa kutha iku nyerah (ing 1403 bakal dibalèkaké marang Bizantium lan ing 1430 ditaklukaké sacara pungkasan). Panggonan liya sing digabungake ing tanggal sing padha: Kavala. Pamukiman liya sing ucul ing tanggal sing padha: Langadas, Eleftheroupoli (Praviște).", "834119a2"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Ekspedisi Bulgaria Çandarlı Ali Pasya: direbuté Shumen lan Ruse", "2781c3a9"], "d": ["Bèntèng-bèntèng Ketsaran Bulgaria ing sadawané Kali Donau ditampa penyerahané ing siji ekspedisi; aja dikacoaké karo kekalahan ing Bileća ing Bosnia ing taun sing padha — iki suksès bebarengan ing front sing béda. Tarnovo lan Vidin dadi pusat Bulgaria pungkasan sing isih dicekel.", "d6eaf4cd"]}
});
